import{d as j,C as y,o as f,c as k,j as n,a as e,E as a,a3 as P}from"./chunks/framework.D4-ViStF.js";const G=JSON.parse('{"title":"庄子·人间世","description":"从心斋、不得已到无用之用，理解庄子如何在险恶的人间保全自身。","frontmatter":{"title":"庄子·人间世","description":"从心斋、不得已到无用之用，理解庄子如何在险恶的人间保全自身。","category":"guide","aliases":["人间世","庄子人间世","zhuangzi chapter 04"],"source":["《庄子》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-04.md","filePath":"daoism/zhuang-zi/chapter-04.md","lastUpdated":1788516578000}'),T={name:"daoism/zhuang-zi/chapter-04.md"},N=j({...T,setup(v){const r=[{id:"xinzhai_s1",label:"颜回见仲尼请行……庶几其国有瘳乎",sentences:[[{text:"颜回",glossary:"yanhui"},"见",{text:"仲尼",glossary:"zhongni"},"，",{text:"请行",glossary:"qing_xing"},"。曰：「",{text:"奚之",glossary:"xi_zhi"},"？」曰：「将",{text:"之卫",glossary:"zhi_wei"},"。」曰：「",{text:"奚为焉",glossary:"xi_wei_yan"},"？」"],["曰：「回闻卫君，其",{text:"年壮",glossary:"nian_zhuang"},"，其",{text:"行独",glossary:"xing_du"},"，",{text:"轻用其国",glossary:"qing_yong_guo"},"，而",{text:"不见其过",glossary:"bu_jian_guo"},"；",{text:"轻用民死",glossary:"qing_yong_minsi"},"，死者",{text:"以国量乎",glossary:"yi_guo_liang"},{text:"泽若蕉",glossary:"ze_ruojiao"},"，",{text:"民其无如矣",glossary:"min_wuruyi"},"。"],[{text:"回尝闻之",glossary:"hui_chang_wen"},"夫子曰：『",{text:"治国去之",glossary:"zhiguo_quzhi"},"，",{text:"乱国就之",glossary:"luanguo_jiuzhi"},"，",{text:"医门多疾",glossary:"yimen_duoji"},"。』",{text:"愿",glossary:"yuan_xiwang"},{text:"以",glossary:"yi_yong"},{text:"所闻思",glossary:"suowen_si"},{text:"其则",glossary:"qi_ze"},"，",{text:"庶",glossary:"shu_huoxu"},{text:"几",glossary:"ji_jinnian"},{text:"其国有瘳乎",glossary:"you_chou"},"？」"]]},{id:"xinzhai_s2",label:"仲尼曰嘻若殆往而刑耳……非所以尽行也",sentences:[["仲尼曰：「嘻！",{text:"若殆往",glossary:"ruo_dai_wang"},{text:"而",glossary:"er_zhi"},{text:"刑耳",glossary:"xing_er"},"！"],["夫道不",{text:"欲",glossary:"yu_xihao"},{text:"杂",glossary:"za_hunza"},"，",{text:"杂则多",glossary:"za_duo"},"，",{text:"多则扰",glossary:"duo_rao"},"，",{text:"扰则忧",glossary:"rao_you"},"，",{text:"忧则不救矣",glossary:"you_bujiu"},"。"],[{text:"古之至人",glossary:"guzhi_zhiren"},"，",{text:"先存诸己",glossary:"xian_cun_zhuji"},"而",{text:"后存诸人",glossary:"hou_cun_zhuren"},"。",{text:"所存于己者",glossary:"suocun_yuji"},{text:"未定",glossary:"wei_ding"},"，",{text:"何暇",glossary:"he_xia"},"至于",{text:"暴人",glossary:"bao_ren"},{text:"之所行",glossary:"zhi_suoxing"},"！"],[{text:"且",glossary:"qie_qiecie"},"若亦知",{text:"夫德之所荡",glossary:"de_suodang"},"而",{text:"知之所为出乎哉",glossary:"zhi_suowei_chu"},"？"],[{text:"德荡乎名",glossary:"de_dang_ming"},"，",{text:"知出乎争",glossary:"zhi_chu_zheng"},"。"],[{text:"名也者，相轧也",glossary:"ming_xiangya"},"；",{text:"知也者，争之器也",glossary:"zhi_zhengqi"},"。"],[{text:"二者凶器",glossary:"liangzhe_xiongqi"},"，非所以",{text:"尽行也",glossary:"jin_xing"},"。」"]]},{id:"xinzhai_s3",label:"且德厚信矼……若殆为人菑夫",sentences:[["「且",{text:"德厚信矼",glossary:"de_hou_xin_gang"},"，",{text:"未达人气",glossary:"wei_da_renqi"},"；",{text:"名闻不争",glossary:"ming_wen_buzheng"},"，",{text:"未达人心",glossary:"wei_da_renxin"},"。"],["而",{text:"强",glossary:"qiang_qiangxing"},"以仁义",{text:"绳墨之言术",glossary:"shengmo_yanshu"},{text:"暴人之前",glossary:"bao_ren_qian"},"，是以人",{text:"恶有其美也",glossary:"wu_youqimei"},"，",{text:"命",glossary:"ming_chengwei"},"之曰",{text:"菑人",glossary:"zi_ren"},"。"],[{text:"菑人者，人必反菑之",glossary:"zi_fan_zi"},"，",{text:"若",glossary:"ruo_ni"},{text:"殆为人菑夫",glossary:"dai_weiren_zi"},"！」"]]},{id:"xinzhai_s4",label:"且苟为悦贤而恶不肖……必死于暴人之前矣",sentences:[["「且",{text:"苟",glossary:"gou_ruoguo"},"为",{text:"悦贤",glossary:"yue_xian"},"而",{text:"恶不肖",glossary:"wu_buxiao"},"，恶用而",{text:"求有以异",glossary:"qiu_youyiyi"},"？"],[{text:"若唯无诏",glossary:"ruo_wuzhao"},"，王公必将乘人而",{text:"斗其捷",glossary:"dou_qijie"},"。"],[{text:"而目将荧之",glossary:"mu_yingzhi"},"，",{text:"而色将平之",glossary:"se_pingzhi"},"，",{text:"口将营之",glossary:"kou_yingzhi"},"，",{text:"容将形之",glossary:"rong_xingzhi"},"，",{text:"心且成之",glossary:"xin_chengzhi"},"。"],["是以火救火，以水救水，名之曰",{text:"益多",glossary:"yi_duo"},"。",{text:"顺始无穷",glossary:"shun_shi_wuqiong"},"，",{text:"若殆",glossary:"ruo_dai2"},"以",{text:"不信厚言",glossary:"buxin_houyan"},"，必死于暴人之前矣！」"]]},{id:"xinzhai_s5",label:"且昔者桀杀关龙逢……尝以语我来",sentences:[["「且昔者",{text:"桀",glossary:"jie_wang"},{text:"杀",glossary:"sha_shasi"},{text:"关龙逢",glossary:"guan_longpeng"},"，",{text:"纣",glossary:"zhou_wang"},{text:"杀",glossary:"sha_shasi"},"王子",{text:"比干",glossary:"bi_gan"},"，"],["是皆修其身以",{text:"下伛拊人",glossary:"xia_yufu_ren"},"之民，以下",{text:"拂其上者也",glossary:"fu_qi_shang"},"，故其君因其",{text:"修以挤之",glossary:"xiu_yi_jizhi"},"。"],["是",{text:"好名者也",glossary:"hao_ming"},"。"],["昔者",{text:"尧",glossary:"yao_wang"},{text:"攻",glossary:"gong_gongda"},{text:"丛枝",glossary:"cong_zhi"},"、",{text:"胥敖",glossary:"xu_ao"},"，",{text:"禹",glossary:"yu_wang"},{text:"攻",glossary:"gong_gongda"},{text:"有扈",glossary:"you_hu"},"，",{text:"国为虚厉",glossary:"guo_xuli"},"，",{text:"身为刑戮",glossary:"shen_xinglv"},"。"],[{text:"用兵不止",glossary:"yongbing_buzhi"},"，",{text:"求实无已",glossary:"qiushi_wuyi"},"。是皆",{text:"求名实者也",glossary:"qiu_mingshi"},"，而",{text:"独",glossary:"du_nandao"},"不闻之乎？"],["名实者，圣人之所不能胜也，而况",{text:"若乎",glossary:"ruo_hu"},"！虽然，若必",{text:"有以也",glossary:"you_yi_ye"},"，",{text:"尝",glossary:"chang_qingshi"},"以语我来！」"]]},{id:"xinzhai_s6",label:"颜回曰端而虚……则可乎",sentences:[["颜回曰：「",{text:"端而虚",glossary:"duan_er_xu"},"，",{text:"勉而一",glossary:"mian_er_yi"},"，则可乎？」"]]},{id:"xinzhai_s7",label:"曰恶恶可……故忿设无由巧言偏辞",sentences:[["曰：「",{text:"恶",glossary:"e_buhao"},"！",{text:"恶可",glossary:"e_keyi"},"！夫",{text:"以阳",glossary:"yi_yang"},{text:"为充孔扬",glossary:"chong_kongyang"},"，",{text:"采色不定",glossary:"caise_buding"},"，常人之所",{text:"不违",glossary:"bu_wei"},"，因",{text:"案人之所感",glossary:"an_ren_suogan"},"，以求",{text:"容与其心",glossary:"rong_yu_xin"},"。"],["名之曰",{text:"日渐之",glossary:"ri_jian"},"，",{text:"德不成",glossary:"de_bucheng"},"，而况",{text:"大德",glossary:"da_de"},"乎！"],[{text:"将执而不化",glossary:"zhi_er_buhua"},"，",{text:"外合",glossary:"wai_he"},"而",{text:"内不訾",glossary:"nei_buzi"},"，",{text:"其庸讵可乎",glossary:"yong_ju_ke"},"！",{text:"则若亦殆矣",glossary:"ze_ruo_dai"},"。"],["且",{text:"以巧斗力者",glossary:"qiao_douli"},"，",{text:"始乎阳",glossary:"shi_yang"},"，常",{text:"卒乎阴",glossary:"zu_yin"},"，",{text:"大至",glossary:"da_zhi"},"则多",{text:"奇巧",glossary:"qi_qiao"},"；"],["以",{text:"礼",glossary:"li_liyi"},"饮酒者，",{text:"始乎治",glossary:"shi_zhi"},"，",{text:"常",glossary:"chang_wangwang"},{text:"卒乎乱",glossary:"zu_luan"},"，大至则多",{text:"奇乐",glossary:"qi_le"},"。"],[{text:"凡事亦然",glossary:"fanshi_yiran"},"，始乎",{text:"谅",glossary:"liang_chengxin"},"，常卒乎",{text:"鄙",glossary:"bi_beilou"},"，其作始也",{text:"简",glossary:"jian_jiandan"},"，其将毕也必",{text:"巨",glossary:"ju_juda"},"。"],[{text:"言者，风波也",glossary:"yan_fengbo"},"；",{text:"行者，实丧也",glossary:"xing_sangshi"},"。"],[{text:"风波易以动",glossary:"fengbo_yi_dong"},"，",{text:"实丧易以危",glossary:"sangshi_yi_wei"},"。"],["故",{text:"忿设无由",glossary:"fen_she_wuyou"},"，",{text:"巧言偏辞",glossary:"qiao_yan_pianci"},"。」"]]},{id:"xinzhai_s8",label:"仲尼曰若一志……虚者心斋也",sentences:[["仲尼曰：「",{text:"若一志",glossary:"ruo_yizhi"},"，",{text:"无听之以耳",glossary:"wu_ting_er"},"而",{text:"听之以心",glossary:"ting_xin"},"，",{text:"无听之以心",glossary:"wu_ting_xin"},"而",{text:"听之以气",glossary:"ting_qi"},"。"],[{text:"听止于耳",glossary:"ting_zhi_er"},"，",{text:"心止于符",glossary:"xin_zhi_fu"},"。"],[{text:"气也者，虚而待物者也",glossary:"qi_xu_daiwu"},"。"],[{text:"唯道集虚",glossary:"dao_ji_xu"},"，",{text:"虚者，心斋也",glossary:"xu_xinzhai"},"。」"]]},{id:"xinzhai_s9",label:"颜回曰回之未始得使……可谓虚乎",sentences:[["颜回曰：「回之",{text:"未始得使",glossary:"weishi_deshi"},"，",{text:"实自回也",glossary:"shi_zi_hui"},"；",{text:"得使之也",glossary:"de_shizhi"},"，",{text:"未始有回也",glossary:"weishi_you_hui"},"。可谓",{text:"虚",glossary:"xu_kong"},"乎？」"]]},{id:"xinzhai_s10",label:"夫子曰尽矣……而况散焉者乎",sentences:[["夫子曰：「",{text:"尽矣",glossary:"jin_yi"},"！吾语若：若能入游其",{text:"樊",glossary:"fan_fanlong"},"而",{text:"无感其名",glossary:"wu_gan_ming"},"，",{text:"入则鸣",glossary:"ru_ze_ming"},"，",{text:"不入则止",glossary:"buru_ze_zhi"},"。"],[{text:"无门无毒",glossary:"wu_men_wu_du"},"，",{text:"一宅而寓",glossary:"yi_zhai_yu"},"于",{text:"不得已",glossary:"bu_deyi"},"，则",{text:"几矣",glossary:"ji_yi"},"。"],[{text:"绝迹易",glossary:"jue_ji_yi"},"，",{text:"无行地难",glossary:"wu_xingdi_nan"},"。"],["为人",{text:"使易以伪",glossary:"shi_yi_wei"},"，为",{text:"天",glossary:"tian_ziran"},{text:"使难以伪",glossary:"tian_shi_nan_wei"},"。"],["闻以有翼飞者矣，未闻以无翼飞者也；闻以有知知者矣，未闻以无知知者也。"],[{text:"瞻彼阕者",glossary:"zhan_que"},"，",{text:"虚室生白",glossary:"xu_shi_shengbai"},"，",{text:"吉祥止止",glossary:"jixiang_zhizhi"},"。"],[{text:"夫且不止",glossary:"fu_qie_buzhi"},"，是之谓",{text:"坐驰",glossary:"zuo_chi"},"。"],["夫",{text:"徇",glossary:"xun_shunying"},"耳目内通而外于心知，鬼神将",{text:"来舍",glossary:"lai_she"},"，而况人乎！"],["是",{text:"万物之化也",glossary:"wanwu_zhi_hua"},"，禹、舜",{text:"之所纽也",glossary:"zhi_suo_niu"},"，",{text:"伏戏",glossary:"fu_xi"},"、",{text:"几蘧",glossary:"ji_qu"},{text:"之所行终",glossary:"zhi_suoxing_zhong"},"，而况",{text:"散焉者乎",glossary:"san_yan_zhe"},"！」"]]}],m=[{id:"yanhui",term:"颜回",pinyin:"yán huí",meaning:"孔子最得意的弟子，字子渊。本篇以颜回问道为线索，展开「心斋」的核心论述。"},{id:"zhongni",term:"仲尼",pinyin:"zhòng ní",meaning:"孔子的字。此处庄子借孔子之口阐发道家思想，非历史上的孔子。"},{id:"qing_xing",term:"请行",pinyin:"qǐng xíng",meaning:"请求出行、请求前往。请：请求；行：出行。"},{id:"xi_zhi",term:"奚之",pinyin:"xī zhī",meaning:"去哪里？奚：哪里，疑问代词；之：去、往，动词。"},{id:"zhi_wei",term:"将之卫",pinyin:"jiāng zhī wèi",meaning:"将要去卫国。之：往、去，动词；卫：卫国。"},{id:"xi_wei_yan",term:"奚为焉",pinyin:"xī wéi yān",meaning:"去那里做什么？奚为：做什么；焉：在那里，兼词（于此）。"},{id:"nian_zhuang",term:"年壮",pinyin:"nián zhuàng",meaning:"年轻气盛。壮：壮年、血气方刚。"},{id:"xing_du",term:"行独",pinyin:"xíng dú",meaning:"行事独断专行。行：行为、处事；独：独断、独行其是。"},{id:"qing_yong_guo",term:"轻用其国",pinyin:"qīng yòng qí guó",meaning:"轻率地使用（挥霍）国家资源。轻：轻率、随意；用：使用、挥霍。"},{id:"bu_jian_guo",term:"不见其过",pinyin:"bù jiàn qí guò",meaning:"看不见自己的过失。见：看见、察觉；过：过失、错误。"},{id:"qing_yong_minsi",term:"轻用民死",pinyin:"qīng yòng mín sǐ",meaning:"轻率地让百姓送死。轻用：随意使用；民死：百姓的生命。"},{id:"yi_guo_liang",term:"以国量乎",pinyin:"yǐ guó liàng hū",meaning:"用国家（的范围）来衡量（死亡人数之多）。以：用；国量：以国土为单位来计量。"},{id:"ze_ruojiao",term:"泽若蕉",pinyin:"zé ruò jiāo",meaning:"（死者）遍布沼泽如同芭蕉叶一样（铺满大地）。泽：沼泽；若：如同；蕉：芭蕉叶，叶大而多，喻死者之众。"},{id:"min_wuruyi",term:"民其无如矣",pinyin:"mín qí wú rú yǐ",meaning:"百姓无处可去、无可奈何了。无如：无可奈何、无处可去；矣：语气词，表感叹。"},{id:"hui_chang_wen",term:"回尝闻之",pinyin:"huí cháng wén zhī",meaning:"我（颜回）曾经听说过。尝：曾经；之：代词，指下文所引夫子之言。"},{id:"zhiguo_quzhi",term:"治国去之",pinyin:"zhì guó qù zhī",meaning:"治理得好的国家就离开它。治国：治理良好的国家；去：离开；之：代词，指治国。"},{id:"luanguo_jiuzhi",term:"乱国就之",pinyin:"luàn guó jiù zhī",meaning:"动乱的国家就前往它。乱国：动乱的国家；就：前往、靠近。"},{id:"yimen_duoji",term:"医门多疾",pinyin:"yī mén duō jí",meaning:"医生门前病人多。喻有道之人应去乱国救世，如医者聚于病患之处。"},{id:"yuan_xiwang",term:"愿",pinyin:"yuàn",meaning:"希望、愿意。表达颜回的意愿。"},{id:"yi_yong",term:"以",pinyin:"yǐ",meaning:"用、凭借。以所闻思其则：用所听到的道理来思考应对的方法。"},{id:"suowen_si",term:"所闻思",pinyin:"suǒ wén sī",meaning:"所听到的（道理）来思考。所闻：所听到的；思：思考、推演。"},{id:"qi_ze",term:"其则",pinyin:"qí zé",meaning:"那（治国）的方法、准则。其：那；则：方法、准则。"},{id:"shu_huoxu",term:"庶",pinyin:"shù",meaning:"也许、或许。表示希望的副词。庶几：也许……吧。"},{id:"ji_jinnian",term:"几",pinyin:"jī",meaning:"接近、差不多。庶几：也许差不多……。【古今异义】非「几乎/多少」，此处与「庶」连用表希望。"},{id:"you_chou",term:"其国有瘳乎",pinyin:"qí guó yǒu chōu hū",meaning:"那个国家有痊愈（好转）的希望吗？瘳：病愈、好转；乎：疑问语气词。【古今异义】瘳：病愈，非常用字。"},{id:"ruo_dai_wang",term:"若殆往",pinyin:"ruò dài wǎng",meaning:"你只怕去了（就有危险）。若：你；殆：恐怕、只怕；往：前往。"},{id:"er_zhi",term:"而",pinyin:"ér",meaning:"就、便。连词，表顺承。若殆往而刑耳：你去了恐怕就会受刑罚罢了。"},{id:"xing_er",term:"刑耳",pinyin:"xíng ěr",meaning:"受刑罚罢了。刑：受刑、被处罚；耳：罢了，限定语气词。"},{id:"yu_xihao",term:"欲",pinyin:"yù",meaning:"喜好、希望。道不欲杂：道不喜欢（被）混杂。"},{id:"za_hunza",term:"杂",pinyin:"zá",meaning:"混杂、杂乱。道不欲杂：道一旦混杂就会出问题。"},{id:"za_duo",term:"杂则多",pinyin:"zá zé duō",meaning:"混杂了就会繁多（头绪纷乱）。多：繁多、杂乱。"},{id:"duo_rao",term:"多则扰",pinyin:"duō zé rǎo",meaning:"繁多了就会扰乱（心神）。扰：扰乱、纷扰。"},{id:"rao_you",term:"扰则忧",pinyin:"rǎo zé yōu",meaning:"扰乱了就会产生忧虑。忧：忧虑、焦虑。"},{id:"you_bujiu",term:"忧则不救矣",pinyin:"yōu zé bù jiù yǐ",meaning:"忧虑了就无可救药了。不救：无法救治、无可挽回。杂→多→扰→忧→不救，五步递进，说明道不可杂。"},{id:"guzhi_zhiren",term:"古之至人",pinyin:"gǔ zhī zhì rén",meaning:"古代的至道之人。至人：达到最高境界的人，庄子理想人格之一。"},{id:"xian_cun_zhuji",term:"先存诸己",pinyin:"xiān cún zhū jǐ",meaning:"先使自身（的道）稳固。存：存养、稳固；诸：之于，兼词；己：自身。"},{id:"hou_cun_zhuren",term:"后存诸人",pinyin:"hòu cún zhū rén",meaning:"然后再去稳固他人（的道）。诸人：之于他人。先己后人，是施教的根本次序。"},{id:"suocun_yuji",term:"所存于己者",pinyin:"suǒ cún yú jǐ zhě",meaning:"自身所存养的（道）。所存于己：在自身中所存养的道德修养。"},{id:"wei_ding",term:"未定",pinyin:"wèi dìng",meaning:"尚未稳固、尚未确立。未：尚未；定：稳定、确立。"},{id:"he_xia",term:"何暇",pinyin:"hé xiá",meaning:"哪有闲暇、哪里来得及。何：哪里；暇：空闲、余暇。"},{id:"bao_ren",term:"暴人",pinyin:"bào rén",meaning:"暴虐之人、暴君。暴：暴虐、残暴。此处指卫君。"},{id:"zhi_suoxing",term:"之所行",pinyin:"zhī suǒ xíng",meaning:"所作所为。之：助词；所行：所做的事情。"},{id:"qie_qiecie",term:"且",pinyin:"qiě",meaning:"况且、再说。连词，表递进，引出新的论点。"},{id:"de_suodang",term:"夫德之所荡",pinyin:"fū dé zhī suǒ dàng",meaning:"德被动摇的原因所在。荡：动摇、散失；所荡：被动摇的地方/原因。"},{id:"zhi_suowei_chu",term:"知之所为出乎哉",pinyin:"zhī zhī suǒ wéi chū hū zāi",meaning:"智慧从哪里产生出来的呢？知：智慧；所为出：所从出，产生的来源；乎哉：疑问语气。"},{id:"de_dang_ming",term:"德荡乎名",pinyin:"dé dàng hū míng",meaning:"德被名声所动摇。荡：动摇；乎：被，介词；名：名声、名誉。"},{id:"zhi_chu_zheng",term:"知出乎争",pinyin:"zhī chū hū zhēng",meaning:"智慧产生于争竞。出：产生；乎：于，介词；争：争竞、竞争。"},{id:"ming_xiangya",term:"名也者，相轧也",pinyin:"míng yě zhě xiāng yà yě",meaning:"名声这东西，是人们相互倾轧的根源。轧：碾压、倾轧；相轧：互相倾轧争压。"},{id:"zhi_zhengqi",term:"知也者，争之器也",pinyin:"zhī yě zhě zhēng zhī qì yě",meaning:"智慧这东西，是争斗的工具。争之器：用于争斗的器具。"},{id:"liangzhe_xiongqi",term:"二者凶器",pinyin:"èr zhě xiōng qì",meaning:"这两者（名与知）都是凶险的器具。凶器：危险的工具，非现代「凶器」专指杀人武器。"},{id:"jin_xing",term:"尽行也",pinyin:"jìn xíng yě",meaning:"可以完全推行的。尽：完全、彻底；行：推行、实行。非所以尽行也：不是可以完全推行的东西。"},{id:"de_hou_xin_gang",term:"德厚信矼",pinyin:"dé hòu xìn gāng",meaning:"德行深厚、信义坚固。德厚：德行深厚；信矼：信义坚实，矼：坚固、坚实，读 gāng。"},{id:"wei_da_renqi",term:"未达人气",pinyin:"wèi dá rén qì",meaning:"还未能通达他人的心气（还未被对方接受）。达：通达、达到；人气：他人的心气、情绪。"},{id:"ming_wen_buzheng",term:"名闻不争",pinyin:"míng wén bù zhēng",meaning:"名声远播且不争竞。名闻：名声广为人知；不争：不与人争。"},{id:"wei_da_renxin",term:"未达人心",pinyin:"wèi dá rén xīn",meaning:"还未能通达他人的内心。达人心：打动、通达对方内心。"},{id:"qiang_qiangxing",term:"强",pinyin:"qiǎng",meaning:"强行、勉强。⚠️ 读 qiǎng，非「强大」。强以仁义绳墨之言：强行用仁义规范的言论（去说服对方）。"},{id:"shengmo_yanshu",term:"绳墨之言术",pinyin:"shéng mò zhī yán shù",meaning:"以仁义为准绳的言辞方法。绳墨：木工用的墨线，比喻规范、准则；言术：言辞的方法。"},{id:"bao_ren_qian",term:"暴人之前",pinyin:"bào rén zhī qián",meaning:"在暴虐之人面前。暴人：暴君；之前：面前。"},{id:"wu_youqimei",term:"恶有其美也",pinyin:"wù yǒu qí měi yě",meaning:"厌恶别人拥有（比自己）美好的（德行）。恶：厌恶，读 wù；有其美：拥有那美好的德行。"},{id:"ming_chengwei",term:"命",pinyin:"mìng",meaning:"称之为、叫做。命之曰：称它为……。"},{id:"zi_ren",term:"菑人",pinyin:"zī rén",meaning:"害人者、给人带来灾祸的人。菑：通「灾」，灾祸；菑人：带来灾祸的人。【通假字】菑通「灾」，读 zī。"},{id:"zi_fan_zi",term:"菑人者，人必反菑之",pinyin:"zī rén zhě rén bì fǎn zī zhī",meaning:"害人者，人必然反过来害他。反菑：反过来加以灾祸。"},{id:"ruo_ni",term:"若",pinyin:"ruò",meaning:"你。第二人称代词。"},{id:"dai_weiren_zi",term:"殆为人菑夫",pinyin:"dài wéi rén zī fū",meaning:"恐怕要被人当作灾祸（而遭反噬）啊。殆：恐怕；为人菑：被人视为灾祸；夫：语气词，表感叹。"},{id:"gou_ruoguo",term:"苟",pinyin:"gǒu",meaning:"如果、假若。连词，表假设。【古今异义】非「苟且」，此处为假设连词「如果」。"},{id:"yue_xian",term:"悦贤",pinyin:"yuè xián",meaning:"喜爱贤能之人。悦：喜爱；贤：贤能者。"},{id:"wu_buxiao",term:"恶不肖",pinyin:"wù bù xiào",meaning:"厌恶不贤之人。恶：厌恶，读 wù；不肖：不才、不贤。"},{id:"qiu_youyiyi",term:"求有以异",pinyin:"qiú yǒu yǐ yì",meaning:"寻求有什么特别之处（来与众不同）。有以异：有所不同、与众不同。"},{id:"ruo_wuzhao",term:"若唯无诏",pinyin:"ruò wéi wú zhào",meaning:"你只是不去告诫（不主动进言）。若：你；唯：只；无诏：不去告诫、不主动进言；诏：告诫、教导。"},{id:"dou_qijie",term:"斗其捷",pinyin:"dòu qí jié",meaning:"争着展示自己的口才敏捷。斗：争斗、竞争；捷：敏捷、机敏，指口才。王公乘人而斗其捷：王公会趁机与你争论口才。"},{id:"mu_yingzhi",term:"目将荧之",pinyin:"mù jiāng yíng zhī",meaning:"眼神将会被迷惑（眼花缭乱）。荧：迷惑、眩惑；之：代词，指颜回。"},{id:"se_pingzhi",term:"色将平之",pinyin:"sè jiāng píng zhī",meaning:"（王公的）脸色将会（故作）平和来应付你。色：脸色；平：平和、平静（伪装）。"},{id:"kou_yingzhi",term:"口将营之",pinyin:"kǒu jiāng yíng zhī",meaning:"言辞将会迷惑你。营：迷惑、蒙蔽。"},{id:"rong_xingzhi",term:"容将形之",pinyin:"róng jiāng xíng zhī",meaning:"仪容将会（做出顺从的）表现来应付你。容：仪容；形：表现、显现。"},{id:"xin_chengzhi",term:"心且成之",pinyin:"xīn qiě chéng zhī",meaning:"内心将会（暗中）成全（自己的想法来对付）你。心且成之：内心另有打算。五句并列：目·色·口·容·心，五方面全面应付颜回。"},{id:"yi_duo",term:"益多",pinyin:"yì duō",meaning:"（祸患）越来越多。益：更加、越来越；多：增多。以火救火，以水救水，名之曰益多：用火去救火，用水去救水，只会越来越多（越来越糟）。"},{id:"shun_shi_wuqiong",term:"顺始无穷",pinyin:"shùn shǐ wú qióng",meaning:"顺着这个开头（发展下去）没有穷尽。顺始：顺着这个开端；无穷：没有终止。"},{id:"ruo_dai2",term:"若殆",pinyin:"ruò dài",meaning:"你恐怕。若：你；殆：恐怕。"},{id:"buxin_houyan",term:"以不信厚言",pinyin:"yǐ bù xìn hòu yán",meaning:"凭着不被信任的（却）言辞恳切的话语。不信：不被信任；厚言：言辞恳切、语气诚恳。"},{id:"jie_wang",term:"桀",pinyin:"jié",meaning:"夏朝末代暴君夏桀。以暴虐著称，杀忠臣关龙逢。"},{id:"sha_shasi",term:"杀",pinyin:"shā",meaning:"杀死、处死。"},{id:"guan_longpeng",term:"关龙逢",pinyin:"guān lóng páng",meaning:"夏桀时的忠臣，因直谏而被杀。以忠谏著称，是「好名」而遭祸的典型。"},{id:"zhou_wang",term:"纣",pinyin:"zhòu",meaning:"商朝末代暴君商纣王。以残暴著称，杀忠臣比干。"},{id:"bi_gan",term:"比干",pinyin:"bǐ gān",meaning:"商纣王的叔父，忠臣，因直谏被剖心而死。与关龙逢并列，为「好名」招祸的例证。"},{id:"xia_yufu_ren",term:"下伛拊人",pinyin:"xià yǔ fǔ rén",meaning:"俯身抚慰他人的百姓。下：俯下身；伛：弯腰；拊：抚慰、抚摸；人：他人（君主）的百姓。"},{id:"fu_qi_shang",term:"拂其上者也",pinyin:"fǔ qí shàng zhě yě",meaning:"违逆他们君主的人。拂：违逆、触犯；其上：他们的君主。"},{id:"xiu_yi_jizhi",term:"修以挤之",pinyin:"xiū yǐ jǐ zhī",meaning:"（君主）借他们的（好）名声来排挤、陷害他们。修：美好的名声、修身之名；挤：排挤、陷害。"},{id:"hao_ming",term:"好名者也",pinyin:"hào míng zhě yě",meaning:"追求名声的人。好名：喜好名声；也：判断语气词。"},{id:"yao_wang",term:"尧",pinyin:"yáo",meaning:"上古圣王唐尧。此处庄子以尧为例，说明即便圣王也难逃「求名实」的问题。"},{id:"gong_gongda",term:"攻",pinyin:"gōng",meaning:"攻打、征伐。"},{id:"cong_zhi",term:"丛枝",pinyin:"cóng zhī",meaning:"古代小国名，被尧所攻伐。"},{id:"xu_ao",term:"胥敖",pinyin:"xū áo",meaning:"古代小国名，与丛枝并列，被尧所攻伐。"},{id:"yu_wang",term:"禹",pinyin:"yǔ",meaning:"上古圣王大禹。治水有功，此处庄子以禹攻有扈为例。"},{id:"you_hu",term:"有扈",pinyin:"yǒu hù",meaning:"古代部族名，被禹所攻伐。"},{id:"guo_xuli",term:"国为虚厉",pinyin:"guó wéi xū lì",meaning:"国家变成废墟鬼域。虚：废墟；厉：厉鬼、鬼域，指荒无人烟之地。"},{id:"shen_xinglv",term:"身为刑戮",pinyin:"shēn wéi xíng lù",meaning:"自身遭受刑罚杀戮。刑戮：刑罚与杀戮。"},{id:"yongbing_buzhi",term:"用兵不止",pinyin:"yòng bīng bù zhǐ",meaning:"用兵征伐不停止。"},{id:"qiushi_wuyi",term:"求实无已",pinyin:"qiú shí wú yǐ",meaning:"追求实利没有止境。实：实利、实际利益；无已：没有终止。"},{id:"qiu_mingshi",term:"求名实者也",pinyin:"qiú míng shí zhě yě",meaning:"追求名声与实利的人。名实：名声与实利，儒家重名，法家重实，庄子认为两者皆不可执。"},{id:"du_nandao",term:"独",pinyin:"dú",meaning:"难道、偏偏。副词，表反问。独不闻之乎：难道没有听说过吗？"},{id:"ruo_hu",term:"而况若乎",pinyin:"ér kuàng ruò hū",meaning:"何况是你呢？而况：更何况；若：你。圣人尚且不能胜，何况颜回。"},{id:"you_yi_ye",term:"有以也",pinyin:"yǒu yǐ yě",meaning:"有（什么办法/想法）的。有以：有所凭借、有办法；也：语气词。若必有以也：你必定有什么想法（办法）。"},{id:"chang_qingshi",term:"尝",pinyin:"cháng",meaning:"试着、姑且。副词。尝以语我来：试着告诉我吧。"},{id:"duan_er_xu",term:"端而虚",pinyin:"duān ér xū",meaning:"端正而内心虚静。端：端正、正直；虚：虚静、空明。"},{id:"mian_er_yi",term:"勉而一",pinyin:"miǎn ér yī",meaning:"努力而专一。勉：努力、勤勉；一：专一、心志统一。"},{id:"e_buhao",term:"恶",pinyin:"wū",meaning:"哎、唉。感叹词，表否定或惊叹。⚠️ 读 wū，非「恶evil」。"},{id:"e_keyi",term:"恶可",pinyin:"wū kě",meaning:"怎么可以！恶：怎么（读 wū），疑问副词；可：可以。表示强烈否定与惊叹。"},{id:"yi_yang",term:"以阳",pinyin:"yǐ yáng",meaning:"用外露的阳气（虚张声势）。以：用；阳：表面的阳性、外露的强势。夫以阳为充孔扬：他凭借外露的阳气而气充内、势外扬。"},{id:"chong_kongyang",term:"为充孔扬",pinyin:"wéi chōng kǒng yáng",meaning:"气充于内而甚为张扬。充：充满；孔：甚、很；扬：张扬外露。形容卫君骄气盛气凌人。"},{id:"caise_buding",term:"采色不定",pinyin:"cǎi sè bù dìng",meaning:"神色变化不定。采色：神色、脸色；定：稳定。指喜怒无常、难以揣测。"},{id:"bu_wei",term:"不违",pinyin:"bù wéi",meaning:"不敢违抗。常人之所不违：常人都不敢违抗他（卫君）。"},{id:"an_ren_suogan",term:"案人之所感",pinyin:"àn rén zhī suǒ gǎn",meaning:"压制人们的情感。案：通「按」，压制、按抑；所感：情感、感受。【通假字】案通「按」。"},{id:"rong_yu_xin",term:"容与其心",pinyin:"róng yǔ qí xīn",meaning:"放纵（迎合）自己的心意。容与：放纵、放任。以求容与其心：以求放纵自己的心意。"},{id:"ri_jian",term:"日渐之",pinyin:"rì jiān zhī",meaning:"日益渐进的（修养）。日渐：每日渐进；之：助词。名之曰日渐之德不成：即使叫它每日渐进的小德尚且不能成就。"},{id:"de_bucheng",term:"德不成",pinyin:"dé bù chéng",meaning:"德行不能成就。与「日渐」连用：渐进的小德尚且不成。"},{id:"da_de",term:"大德",pinyin:"dà dé",meaning:"大德（大道）。而况大德乎：何况大德（大道）呢？"},{id:"zhi_er_buhua",term:"将执而不化",pinyin:"zhí ér bù huà",meaning:"固执而不知变化（变通）。执：固执；化：变化、化解。指对方执拗顽固，无法感化。"},{id:"wai_he",term:"外合",pinyin:"wài hé",meaning:"外表附和。外合而内不訾：表面附和而内心不认同。"},{id:"nei_buzi",term:"内不訾",pinyin:"nèi bù zī",meaning:"内心并不（真心）认同。訾：非议、认同，读 zī。与「外合」对举：貌合神离。"},{id:"yong_ju_ke",term:"其庸讵可乎",pinyin:"qí yōng jù kě hū",meaning:"那怎么可以呢？庸讵：怎么、难道；可：可以。反问语气，表坚决否定。"},{id:"ze_ruo_dai",term:"则若亦殆矣",pinyin:"zé ruò yì dài yǐ",meaning:"那你也就危险了。则：那么；若：你；殆：危险；矣：语气词。"},{id:"qiao_douli",term:"以巧斗力者",pinyin:"yǐ qiǎo dòu lì zhě",meaning:"用机巧角力竞争的人。巧：机巧、技巧；斗力：角力。喻用心机相争者。"},{id:"shi_yang",term:"始乎阳",pinyin:"shǐ hū yáng",meaning:"开始于光明正大。阳：公开、正大。始乎阳，常卒乎阴：开始光明正大，最终往往流于阴险。"},{id:"zu_yin",term:"卒乎阴",pinyin:"zú hū yīn",meaning:"最终流于阴暗（使用阴谋）。卒：最终；阴：阴险、阴谋。与「始乎阳」对举。"},{id:"da_zhi",term:"大至",pinyin:"dà zhì",meaning:"发展到极点。大至则多奇巧：发展到极点就多出奇诈的手段。"},{id:"qi_qiao",term:"奇巧",pinyin:"qí qiǎo",meaning:"奇诡的机巧（诈术）。奇：诡诈、失度；巧：机巧。"},{id:"li_liyi",term:"礼",pinyin:"lǐ",meaning:"礼（饮酒的礼仪）。以礼饮酒者：遵循礼仪饮酒的人。与「以巧斗力」对举，喻有规范的竞争。"},{id:"shi_zhi",term:"始乎治",pinyin:"shǐ hū zhì",meaning:"开始于合乎秩序（礼仪井然）。治：有秩序、有条理。"},{id:"chang_wangwang",term:"常",pinyin:"cháng",meaning:"往往、常常。副词。常卒乎乱：往往最终陷入混乱。"},{id:"zu_luan",term:"卒乎乱",pinyin:"zú hū luàn",meaning:"最终陷入混乱。与「始乎治」对举：开始有序，最终失序。"},{id:"qi_le",term:"奇乐",pinyin:"qí lè",meaning:"失度的狂欢（乐极生乱）。奇：过分、失度；乐：欢乐。"},{id:"fanshi_yiran",term:"凡事亦然",pinyin:"fán shì yì rán",meaning:"凡事都是这样。凡：凡是；亦然：也是这样。总括上文，引出下文的普遍规律。"},{id:"liang_chengxin",term:"谅",pinyin:"liàng",meaning:"诚信、诚实。始乎谅：开始时出于诚信。"},{id:"bi_beilou",term:"鄙",pinyin:"bǐ",meaning:"鄙陋（卑劣）。常卒乎鄙：往往最终流于鄙陋。"},{id:"jian_jiandan",term:"简",pinyin:"jiǎn",meaning:"简单。其作始也简：事情开始时简单。"},{id:"ju_juda",term:"巨",pinyin:"jù",meaning:"巨大（难以收拾）。其将毕也必巨：到将要结束时必然变得巨大复杂。"},{id:"yan_fengbo",term:"言者，风波也",pinyin:"yán zhě fēng bō yě",meaning:"言语这东西，是风波（的根源）。言者：言语；风波：风波。强调言辞能引起风波。"},{id:"xing_sangshi",term:"行者，实丧也",pinyin:"xíng zhě shí sàng yě",meaning:"行动（作为）这东西，是实利丧失（的根源）。行：行为；实丧：实利丧失。与「言者风波也」对举。"},{id:"fengbo_yi_dong",term:"风波易以动",pinyin:"fēng bō yì yǐ dòng",meaning:"风波容易引起动荡。易以动：容易因此动乱。"},{id:"sangshi_yi_wei",term:"实丧易以危",pinyin:"shí sàng yì yǐ wēi",meaning:"实利丧失容易招致危险。实丧：实际利益的丧失；危：危险。"},{id:"fen_she_wuyou",term:"忿设无由",pinyin:"fèn shè wú yóu",meaning:"愤怒的产生往往没有来由。忿：愤怒；设：产生；无由：没有缘由。喻愤怒常因言辞风波莫名而起。"},{id:"qiao_yan_pianci",term:"巧言偏辞",pinyin:"qiǎo yán piān cí",meaning:"巧诈的言语、偏颇的言辞。巧言：花言巧语；偏辞：偏颇失实的言辞。"},{id:"ruo_yizhi",term:"若一志",pinyin:"ruò yī zhì",meaning:"你要专一你的心志。若：你；一：专一（使动）；志：心志。心斋入手的第一步。"},{id:"wu_ting_er",term:"无听之以耳",pinyin:"wú tīng zhī yǐ ěr",meaning:"不要用耳朵去听。无：不要；听之以耳：用耳听。心斋的三层递听：耳→心→气。"},{id:"ting_xin",term:"听之以心",pinyin:"tīng zhī yǐ xīn",meaning:"用心去听。比用耳听更深一层：不以感官而以心去感应。"},{id:"wu_ting_xin",term:"无听之以心",pinyin:"wú tīng zhī yǐ xīn",meaning:"不要用心去听。心尚有执着分别，需再超越。"},{id:"ting_qi",term:"听之以气",pinyin:"tīng zhī yǐ qì",meaning:"用气去听。气：虚而能纳万物的本然状态——最高的听，即虚心以应。"},{id:"ting_zhi_er",term:"听止于耳",pinyin:"tīng zhǐ yú ěr",meaning:"听觉止于耳朵（耳朵只能听声）。止：局限于、止于。"},{id:"xin_zhi_fu",term:"心止于符",pinyin:"xīn zhǐ yú fú",meaning:"心知止于与外物相合（心的感应止于符号、表象）。符：符合、感应。耳听声、心感物，皆有所止——唯有气虚无待。"},{id:"qi_xu_daiwu",term:"气也者，虚而待物者也",pinyin:"qì yě zhě xū ér dài wù zhě yě",meaning:"气这种东西，是虚空而能容纳万物的。虚：虚空；待物：容纳、应对万物。"},{id:"dao_ji_xu",term:"唯道集虚",pinyin:"wéi dào jí xū",meaning:"只有道能凝聚于虚空（之境）。集：凝聚、汇聚；虚：虚空之境。道只存在于虚静中。"},{id:"xu_xinzhai",term:"虚者，心斋也",pinyin:"xū zhě xīn zhāi yě",meaning:"虚空（的境界），就是心斋。心斋：心灵的斋戒——排除杂念执见、虚静以待的修养境界。本篇核心命题。"},{id:"weishi_deshi",term:"未始得使",pinyin:"wèi shǐ dé shǐ",meaning:"还不曾得到（心斋的）指教。未始：不曾；得使：得到使令（指教）。"},{id:"shi_zi_hui",term:"实自回也",pinyin:"shí zì huí yě",meaning:"实在还是（执着的）颜回自己。实：确实；自回：仍是回（我）自己。喻尚未忘我。"},{id:"de_shizhi",term:"得使之也",pinyin:"dé shǐ zhī yě",meaning:"得到（心斋的）指教之后。得使：得到传授；之：助词。"},{id:"weishi_you_hui",term:"未始有回也",pinyin:"wèi shǐ yǒu huí yě",meaning:"就不曾再有（执着的）颜回了。未始：不再；有回：有执着的自我。忘我则虚——颜回以体会心斋为「虚」。"},{id:"xu_kong",term:"虚",pinyin:"xū",meaning:"虚空（无我）的境界。颜回问：可算是「虚」了吗？"},{id:"jin_yi",term:"尽矣",pinyin:"jìn yǐ",meaning:"（说得）透彻极了！尽：穷尽、透彻；矣：感叹语气词。孔子赞颜回已把握心斋真谛。"},{id:"fan_fanlong",term:"樊",pinyin:"fán",meaning:"笼子、藩篱。入游其樊：进入（卫国政治的）藩篱之中——喻入世从政。"},{id:"wu_gan_ming",term:"无感其名",pinyin:"wú gǎn qí míng",meaning:"不要被（卫国的）名声所触动。感：触动、感应；名：名声、名利。"},{id:"ru_ze_ming",term:"入则鸣",pinyin:"rù zé míng",meaning:"（话）能被接受就言说。入：可入、听得进；鸣：发声、言说。入则鸣，不入则止：能说则说，不能则止。"},{id:"buru_ze_zhi",term:"不入则止",pinyin:"bù rù zé zhǐ",meaning:"听不进去就停止（不说）。不入：不被接受；止：停止。"},{id:"wu_men_wu_du",term:"无门无毒",pinyin:"wú mén wú dú",meaning:"不设门户、不树目标。门：门径；毒：通「窦」，目标、靶的。喻不标榜自己、不树敌、不留把柄。【通假字】毒通「窦」。"},{id:"yi_zhai_yu",term:"一宅而寓",pinyin:"yī zhái ér yù",meaning:"使精神专一而寄托（于不得已）。一宅：使心灵专注如一（如居一宅）；寓：寄托。"},{id:"bu_deyi",term:"不得已",pinyin:"bù dé yǐ",meaning:"无可奈何、不得不如此（的境遇）。一宅而寓于不得已：专一精神寄托于不得不如此的境遇中——顺其自然、不强求。"},{id:"ji_yi",term:"几矣",pinyin:"jī yǐ",meaning:"就差不多了。几：接近（道）；矣：语气词。则几矣：就接近（心斋的境界）了。"},{id:"jue_ji_yi",term:"绝迹易",pinyin:"jué jì yì",meaning:"不留足迹（不行动、隐遁）容易。绝迹：绝足迹，喻远离尘世。"},{id:"wu_xingdi_nan",term:"无行地难",pinyin:"wú xíng dì nán",meaning:"走路而不沾地（行事而不惹尘）难。行地：行走在地上。喻入世而不染俗之难。"},{id:"shi_yi_wei",term:"使易以伪",pinyin:"shǐ yì yǐ wěi",meaning:"被外在（人事）驱使容易作伪。使：被驱使；伪：作假。"},{id:"tian_ziran",term:"天",pinyin:"tiān",meaning:"天然、自然（的天性驱使）。为天使难以伪：被天性（自然）驱使则难以作假。"},{id:"tian_shi_nan_wei",term:"使难以伪",pinyin:"tiān shǐ nán yǐ wěi",meaning:"被天（本性）驱使则难以作假。天：天然本性。与「使易以伪」对举：顺天而行则诚。"},{id:"zhan_que",term:"瞻彼阕者",pinyin:"zhān bǐ què zhě",meaning:"看那虚空（空明）之处。瞻：看；彼：那；阕：通「缺」，虚空、空明。指观照内心的虚静之境。【通假字】阕通「缺」。"},{id:"xu_shi_shengbai",term:"虚室生白",pinyin:"xū shì shēng bái",meaning:"虚空的心灵生出光明（智慧）。虚室：空室，喻虚静之心；生白：生出光明。心空则明。"},{id:"jixiang_zhizhi",term:"吉祥止止",pinyin:"jí xiáng zhǐ zhǐ",meaning:"吉祥止于虚静之心。止止：止于（虚静的）所止之处——前「止」为动词，后「止」为名词（所止）。"},{id:"fu_qie_buzhi",term:"夫且不止",pinyin:"fú qiě bù zhǐ",meaning:"如果不能止于此（虚静）。夫：发语词；且：如果；不止：不能安止于虚静。"},{id:"zuo_chi",term:"坐驰",pinyin:"zuò chí",meaning:"身坐而心神外驰。坐：静坐；驰：奔驰外驰。喻形坐心不静——心斋的反面。"},{id:"xun_shunying",term:"徇",pinyin:"xùn",meaning:"顺从、随顺。徇耳目内通：让耳目等感官向内通达（不外逐于声色）。"},{id:"lai_she",term:"来舍",pinyin:"lái shè",meaning:"来居住（停留）。舍：居留、止息。鬼神将来舍：连鬼神都会来居留（喻达到极高的神明境界）。"},{id:"wanwu_zhi_hua",term:"万物之化也",pinyin:"wàn wù zhī huà yě",meaning:"是万物的化育（之本）。化：化育、变化。指虚静之心是万物化育的枢纽。"},{id:"zhi_suo_niu",term:"之所纽也",pinyin:"zhī suǒ niǔ yě",meaning:"所维系的关键。纽：枢纽、关键。禹、舜之所纽也：是禹、舜（治理）所依凭的枢纽。"},{id:"fu_xi",term:"伏戏",pinyin:"fú xī",meaning:"即伏羲，上古圣王。传说始画八卦。"},{id:"ji_qu",term:"几蘧",pinyin:"jǐ qú",meaning:"上古圣王名。与伏戏并列，喻上古得道之君。"},{id:"zhi_suoxing_zhong",term:"之所行终",pinyin:"zhī suǒ xíng zhōng",meaning:"所践行并终身行之的。行终：践行到底、终其身而行。伏戏、几蘧之所行终：是伏羲、几蘧终身践行的。"},{id:"san_yan_zhe",term:"散焉者乎",pinyin:"sàn yān zhě hū",meaning:"何况一般散漫（未得道）的人呢？散焉者：散漫无道之人；乎：反问语气。而况散焉者乎：更何况一般普通人呢？"}],_=[{id:"yegong_s1",label:"叶公子高将使于齐……子其有以语我来",sentences:[[{text:"叶公子高",glossary:"yegong_zigao"},"将",{text:"使于齐",glossary:"shi_yuqi"},"，问于仲尼曰：「",{text:"王使诸梁也",glossary:"wang_shi_zhuliang"},{text:"甚重",glossary:"shen_zhong"},"，",{text:"齐之待使者",glossary:"qi_dai_shizhe"},"，",{text:"盖",glossary:"gai_dagai"},{text:"将",glossary:"jiang_jiangyao"},{text:"甚敬",glossary:"shen_jing"},"而",{text:"不急",glossary:"bu_ji"},"。"],[{text:"匹夫",glossary:"pifu"},{text:"犹不可动也",glossary:"you_buke_dong"},"，而况诸侯乎！吾",{text:"甚",glossary:"shen_feichang"},{text:"栗之",glossary:"li_zhi"},"。"],["子常语诸梁也曰：『凡事若小若大，",{text:"寡",glossary:"gua_shao"},"不",{text:"道以欢成",glossary:"dao_huancheng"},"。"],["事若不成，则必有",{text:"人道之患",glossary:"rendao_zhihuan"},"；事若成，则必有",{text:"阴阳之患",glossary:"yinyang_zhihuan"},"。"],["若成若不成而后无患者，唯",{text:"有德者能之",glossary:"youde_zhi"},"。』"],["吾",{text:"食也执",glossary:"shi_ye_zhi"},{text:"粗而不臧",glossary:"cu_buzan"},"，",{text:"爨无欲清",glossary:"cuan_wuyu_qing"},"之人。"],["今吾",{text:"朝受命",glossary:"zhao_shouming"},"而",{text:"夕饮冰",glossary:"xi_yinbing"},"，我",{text:"其内热与",glossary:"qi_neire"},"！"],["吾",{text:"未至乎",glossary:"wei_zhihu"},{text:"事之情",glossary:"shi_zhiqing"},"，而既有",{text:"阴阳之患",glossary:"yinyang_zhihuan"},"矣；事若不成，必有",{text:"人道之患",glossary:"rendao_zhihuan"},"。"],[{text:"是两也",glossary:"shi_liang"},"，为人臣者",{text:"不足以当之",glossary:"buzu_dangzhi"},"，",{text:"子",glossary:"zi_nin"},{text:"其",glossary:"qi_qing"},{text:"有",glossary:"you_you"},{text:"以语我来",glossary:"yi_yu_wo"},"！」"]]},{id:"yegong_s2",label:"仲尼曰天下有大戒二……夫子其行可矣",sentences:[["仲尼曰：「天下有大戒二：其一，",{text:"命也",glossary:"ming_tianming"},"；其一，",{text:"义也",glossary:"yi_dayi"},"。"],["子之爱亲，命也，",{text:"不可解于心",glossary:"buke_jie_xin"},"；臣之事君，义也，",{text:"无适而非君也",glossary:"wu_shi_feijun"},"，",{text:"无所逃于天地之间",glossary:"wu_suo_tao"},"。是之谓大戒。"],["是以夫事其亲者，",{text:"不择地而安之",glossary:"bu_zedi_anzhi"},"，孝之至也；"],["夫事其君者，不择事而安之，忠之盛也；"],[{text:"自事其心者",glossary:"zi_shi_xin"},"，",{text:"哀乐",glossary:"aile_qingxu"},{text:"不易",glossary:"bu_yi_gaibian"},{text:"施乎前",glossary:"shi_hu_qian"},"，知其不可奈何而",{text:"安之若命",glossary:"an_zhi_ruoming"},"，德之至也。"],["为人臣子者，固有所不得已。行事之情而忘其身，",{text:"何暇",glossary:"he_xia2"},"至于",{text:"悦生而恶死",glossary:"yue_sheng_wusi"},"！"],["夫子",{text:"其行可矣",glossary:"qi_xing_ke"},"！」"]]},{id:"yegong_s3",label:"丘请复以所闻……则几乎全",sentences:[["「丘",{text:"请复以所闻",glossary:"qing_fu_suowen"},"：",{text:"凡",glossary:"fan_fanshi"},{text:"交近",glossary:"jiao_jin"},"则必",{text:"相靡以信",glossary:"xiang_mi_xin"},"，",{text:"远",glossary:"jiao_yuan"},"则必忠之以言，",{text:"言必或传之",glossary:"yan_huo_chuan"},"。"],["夫传",{text:"两喜两怒",glossary:"liang_xi_nu"},"之言，",{text:"天下之难者也",glossary:"tianxia_nan"},"。"],["夫两喜必多溢美之言，两怒必多溢恶之言。凡溢之类",{text:"妄",glossary:"wang_wangyan"},"，妄则其信之也",{text:"莫",glossary:"mo_meiren"},"，莫则传言者",{text:"殃",glossary:"yang_zaoyang"},"。"],["故",{text:"法言",glossary:"fa_yan"},"曰：『",{text:"传",glossary:"chuan_chuanda"},"其常情，无传其",{text:"溢言",glossary:"yi_yan"},"，则",{text:"几乎全",glossary:"ji_hu_quan"},"。』」"]]},{id:"yegong_s4",label:"且以巧斗力者……故忿设无由巧言偏辞",sentences:[["「且",{text:"以巧斗力者",glossary:"qiao_douli2"},"，",{text:"始乎阳",glossary:"shi_yang2"},"，常卒乎",{text:"阴",glossary:"zu_yin2"},"，大至则多奇巧；"],["以礼饮酒者，始乎治，常",{text:"卒乎乱",glossary:"zu_luan2"},"，大至则多奇乐。"],["凡事亦然，始乎",{text:"谅",glossary:"liang_chengxin2"},"，常卒乎",{text:"鄙",glossary:"bi_beilou2"},"，其作始也",{text:"简",glossary:"jian_jiandan2"},"，其将",{text:"毕",glossary:"bi_wancheng"},"也必",{text:"巨",glossary:"ju_juda2"},"。"],[{text:"行者，实丧也",glossary:"xing_sangshi2"},"。",{text:"风波易以动",glossary:"fengbo_dong2"},"，",{text:"实丧易以危",glossary:"sangshi_wei2"},"。"],["故",{text:"忿设无由",glossary:"fen_wuyou2"},"，",{text:"巧言偏辞",glossary:"qiao_pianci2"},"。"]]},{id:"yegong_s5",label:"兽死不择音……此其难者",sentences:[["兽死",{text:"不择音",glossary:"bu_ze_yin"},"，气息",{text:"茀然",glossary:"fu_ran"},"，于是",{text:"并生心厉",glossary:"bing_sheng_xinli"},"。"],[{text:"剋核太至",glossary:"ke_he_taizhi"},"，则必有",{text:"不肖之心",glossary:"buxiao_xin"},{text:"应之",glossary:"ying_zhi"},"，而不知其然也。苟为不知其然也，孰知其所",{text:"终",glossary:"zhong_jieguo"},"！"],["故法言曰：『",{text:"无迁令",glossary:"wu_qian_ling"},"，",{text:"无劝成",glossary:"wu_quan_cheng"},"，",{text:"过度益也",glossary:"guodu_yi"},"。"],[{text:"迁令劝成殆事",glossary:"qian_quan_daishi"},"，美成在",{text:"久",glossary:"jiu_changqi"},"，恶成",{text:"不及改",glossary:"bujigai"},"，",{text:"可不慎与",glossary:"ke_bu_shen"},"！』"],["且夫",{text:"乘物",glossary:"cheng_wu"},"以",{text:"游心",glossary:"you_xin"},"，",{text:"托不得已",glossary:"tuo_budeyi"},"以",{text:"养中",glossary:"yang_zhong"},"，",{text:"至矣",glossary:"zhi_yi"},"。"],[{text:"何作为报也",glossary:"he_zuowei_bao"},"！",{text:"莫若为致命",glossary:"mozuo_zhiming"},"，",{text:"此其难者",glossary:"ci_qi_nan"},"。』」"]]}],h=[{id:"yegong_zigao",term:"叶公子高",pinyin:"shè gōng zǐ gāo",meaning:"楚国大夫，封于叶地，故称叶公；名诸梁，字子高。⚠️ 叶读 shè，非「叶子」之叶。以出使齐国之难为由，向孔子请教处世之道。"},{id:"shi_yuqi",term:"使于齐",pinyin:"shǐ yú qí",meaning:"出使到齐国。使：出使，奉命出访；于：到、往；齐：齐国。"},{id:"wang_shi_zhuliang",term:"王使诸梁也",pinyin:"wáng shǐ zhū liáng yě",meaning:"楚王派遣我诸梁（出使）。王：楚王；使：派遣；诸梁：叶公子高的名字；也：语气助词，表停顿。"},{id:"shen_zhong",term:"甚重",pinyin:"shèn zhòng",meaning:"非常重大。甚：非常；重：重大、重要。指出使任务责任重大。"},{id:"qi_dai_shizhe",term:"齐之待使者",pinyin:"qí zhī dài shǐ zhě",meaning:"齐国对待使者（的态度）。待：对待；使者：出使的人。"},{id:"gai_dagai",term:"盖",pinyin:"gài",meaning:"大概、恐怕。副词，表推测。【古今异义】非「盖子」，此处为推测副词。"},{id:"jiang_jiangyao",term:"将",pinyin:"jiāng",meaning:"将要、大概会。副词，表将来或推测。"},{id:"shen_jing",term:"甚敬",pinyin:"shèn jìng",meaning:"非常恭敬（表面上）。甚：非常；敬：恭敬。"},{id:"bu_ji",term:"不急",pinyin:"bù jí",meaning:"不急于（处理使命）。指齐国虽表面恭敬，却拖延不办事。"},{id:"pifu",term:"匹夫",pinyin:"pǐ fū",meaning:"普通百姓、平民。匹：单个；夫：男子。匹夫犹不可动：连普通人都难以说动，何况诸侯。"},{id:"you_buke_dong",term:"犹不可动也",pinyin:"yóu bù kě dòng yě",meaning:"尚且不可以（被言辞）打动。犹：尚且；动：打动、说服。"},{id:"shen_feichang",term:"甚",pinyin:"shèn",meaning:"非常、十分。副词，加强程度。"},{id:"li_zhi",term:"栗之",pinyin:"lì zhī",meaning:"为此感到恐惧战栗。栗：战栗、恐惧；之：代词，指出使之事。"},{id:"gua_shao",term:"寡",pinyin:"guǎ",meaning:"少、鲜少。副词。寡不道以欢成：很少有不靠（两方）相互取悦而成功的。"},{id:"dao_huancheng",term:"道以欢成",pinyin:"dào yǐ huān chéng",meaning:"凭借（双方）相互取悦来促成（事情）。道：凭借、通过；欢：取悦、欢好；成：成功。"},{id:"rendao_zhihuan",term:"人道之患",pinyin:"rén dào zhī huàn",meaning:"来自人事方面的祸患。人道：人事、人为的方面；患：祸患。指事情失败后，君主降罪的祸患。"},{id:"yinyang_zhihuan",term:"阴阳之患",pinyin:"yīn yáng zhī huàn",meaning:"来自阴阳（身心）方面的祸患。阴阳：此处指身心内外的失调；患：祸患。指事情成功后，因过度喜悦或压力导致身心受损的祸患。"},{id:"youde_zhi",term:"有德者能之",pinyin:"yǒu dé zhě néng zhī",meaning:"只有有德行的人才能做到（无患）。有德者：具备德行修养的人；能之：能够做到这一点。"},{id:"shi_ye_zhi",term:"食也执",pinyin:"shí yě zhí",meaning:"饮食方面（我）只吃。食：饮食；也：助词，表停顿；执：持守、只吃。"},{id:"cu_buzan",term:"粗而不臧",pinyin:"cū ér bù zāng",meaning:"粗食而不精美。粗：粗糙简单的食物；臧：好、精美。【古今异义】臧：好，非「臧否」常用义。"},{id:"cuan_wuyu_qing",term:"爨无欲清",pinyin:"cuàn wú yù qīng",meaning:"烧火做饭不需要清凉（不讲究）。爨：烧火做饭，读 cuàn；无欲清：不需要清凉舒适。形容叶公平日生活简朴，却因出使之事焦虑不安。"},{id:"zhao_shouming",term:"朝受命",pinyin:"zhāo shòu mìng",meaning:"早晨接受命令。朝：早晨；受命：接受使命。"},{id:"xi_yinbing",term:"夕饮冰",pinyin:"xī yǐn bīng",meaning:"傍晚就在喝冰水（降火）。夕：傍晚；饮冰：喝冰水。朝受命而夕饮冰：早上接了命令，晚上就焦虑上火到要喝冰水，极言内心焦灼。"},{id:"qi_neire",term:"其内热与",pinyin:"qí nèi rè yú",meaning:"大概是内心焦灼（上火）吧！其：大概；内热：内心焦虑上火；与：语气词，通「欤」，表感叹。"},{id:"wei_zhihu",term:"未至乎",pinyin:"wèi zhì hū",meaning:"还没有到达、还没有涉及到。未至：尚未到达；乎：于，介词。"},{id:"shi_zhiqing",term:"事之情",pinyin:"shì zhī qíng",meaning:"事情的实质、使命的实际内容。情：实情、实质。未至乎事之情：还没有进入到使命的实际阶段。"},{id:"shi_liang",term:"是两也",pinyin:"shì liǎng yě",meaning:"这两种（祸患）。是：这；两：两种，指人道之患与阴阳之患。"},{id:"buzu_dangzhi",term:"不足以当之",pinyin:"bù zú yǐ dāng zhī",meaning:"不足以承受（应对）它们。当：承受、应对；之：代词，指两种祸患。"},{id:"zi_nin",term:"子",pinyin:"zǐ",meaning:"您、先生。第二人称敬称，此处指孔子。"},{id:"qi_qing",term:"其",pinyin:"qí",meaning:"请、希望。副词，表请求语气。子其有以语我来：请您有什么话告诉我吧。"},{id:"you_you",term:"有",pinyin:"yǒu",meaning:"有（什么话/办法）。有以：有所凭借、有什么可以……的。"},{id:"yi_yu_wo",term:"以语我来",pinyin:"yǐ yù wǒ lái",meaning:"来告诉我。以：用来；语：告诉，读 yù；来：语气词，表请求。"},{id:"ming_tianming",term:"命也",pinyin:"mìng yě",meaning:"是天命（的安排）。命：天命、自然的命运；也：判断语气词。子之爱亲，命也：子女爱父母，是天命使然，无法从心中解除。"},{id:"yi_dayi",term:"义也",pinyin:"yì yě",meaning:"是道义（的要求）。义：道义、伦理规范；也：判断语气词。臣之事君，义也：臣子侍奉君主，是道义的要求。"},{id:"buke_jie_xin",term:"不可解于心",pinyin:"bù kě jiě yú xīn",meaning:"无法从内心中解除（割舍）。解：解除、消除；于心：在内心中。"},{id:"wu_shi_feijun",term:"无适而非君也",pinyin:"wú shì ér fēi jūn yě",meaning:"无论去到哪里都有君主（需要侍奉）。无适：无论去哪里；非君：不是君主。即天下无处不是君臣关系。"},{id:"wu_suo_tao",term:"无所逃于天地之间",pinyin:"wú suǒ táo yú tiān dì zhī jiān",meaning:"在天地之间无处可以逃避。逃：逃避；天地之间：整个世界。"},{id:"bu_zedi_anzhi",term:"不择地而安之",pinyin:"bù zé dì ér ān zhī",meaning:"不挑选地方（环境）而安然处之。择地：挑选地方；安之：安然对待。孝之至：孝道的最高境界——无论父母在何处，皆安然侍奉。"},{id:"zi_shi_xin",term:"自事其心者",pinyin:"zì shì qí xīn zhě",meaning:"自我修养内心的人。自事：自我修养、自我侍奉；心：内心。"},{id:"aile_qingxu",term:"哀乐",pinyin:"āi lè",meaning:"悲哀与喜乐。代指一切情绪波动。"},{id:"bu_yi_gaibian",term:"不易",pinyin:"bù yì",meaning:"不轻易改变（内心）。易：改变、动摇。【古今异义】非「不容易」，此处为「不改变」。"},{id:"shi_hu_qian",term:"施乎前",pinyin:"shī hū qián",meaning:"呈现在面前（影响内心）。施：施加、呈现；乎：于，介词；前：面前。哀乐不易施乎前：不轻易让哀乐情绪呈现并影响自己。"},{id:"an_zhi_ruoming",term:"安之若命",pinyin:"ān zhī ruò mìng",meaning:"安然接受它就像接受天命一样。安之：安然对待；若命：如同天命。呼应《养生主》「安时而处顺」。"},{id:"he_xia2",term:"何暇",pinyin:"hé xiá",meaning:"哪有闲暇、哪里来得及。何：哪里；暇：空闲。"},{id:"yue_sheng_wusi",term:"悦生而恶死",pinyin:"yuè shēng ér wù sǐ",meaning:"贪恋生命而厌恶死亡。悦生：喜爱、贪恋生命；恶死：厌恶死亡，读 wù sǐ。呼应《养生主》生死观。"},{id:"qi_xing_ke",term:"其行可矣",pinyin:"qí xíng kě yǐ",meaning:"您可以出发了。其：语气副词，表可以；行：出发、前往；可矣：可以了。"},{id:"qing_fu_suowen",term:"请复以所闻",pinyin:"qǐng fù yǐ suǒ wén",meaning:"请再用我所听到的（道理）（来补充）。请：请允许；复：再、又；以所闻：用所听到的。"},{id:"fan_fanshi",term:"凡",pinyin:"fán",meaning:"凡是、大凡。副词，表概括。"},{id:"jiao_jin",term:"交近",pinyin:"jiāo jìn",meaning:"交往密切的（近交）。近：距离近、关系亲近。"},{id:"xiang_mi_xin",term:"相靡以信",pinyin:"xiāng mí yǐ xìn",meaning:"必定相互以诚信来维系。靡：依附、亲近；以信：凭借诚信。"},{id:"jiao_yuan",term:"远",pinyin:"yuǎn",meaning:"（交往）疏远的（远交）。与「近」对举。远则必忠之以言：疏远的则必须凭借言辞来表达忠诚。"},{id:"yan_huo_chuan",term:"言必或传之",pinyin:"yán bì huò chuán zhī",meaning:"言辞必然有人来传递。或：有人、有时；传之：传递这些话。"},{id:"liang_xi_nu",term:"两喜两怒",pinyin:"liǎng xǐ liǎng nù",meaning:"两方都高兴或两方都愤怒（时的言辞）。两喜：双方都喜悦；两怒：双方都愤怒。传递这两种极端情绪的言辞最难。"},{id:"tianxia_nan",term:"天下之难者也",pinyin:"tiān xià zhī nán zhě yě",meaning:"天下最难的事情。难者：困难的事；也：判断语气词。"},{id:"wang_wangyan",term:"妄",pinyin:"wàng",meaning:"虚妄、夸大失实。凡溢之类妄：凡是过分夸大的（言辞）都属于虚妄。"},{id:"mo_meiren",term:"莫",pinyin:"mò",meaning:"没有人（相信）。莫：无人、没有。妄则其信之也莫：虚妄了就没有人相信。"},{id:"yang_zaoyang",term:"殃",pinyin:"yāng",meaning:"遭受祸殃。莫则传言者殃：没有人相信，传话的人就会遭殃。"},{id:"fa_yan",term:"法言",pinyin:"fǎ yán",meaning:"格言、准则性的话。法：法则、准则；言：言论。"},{id:"chuan_chuanda",term:"传",pinyin:"chuán",meaning:"传达、转达。传其常情：只传达（双方的）真实情况。"},{id:"yi_yan",term:"溢言",pinyin:"yì yán",meaning:"过分夸大的言辞。溢：溢出、过分；言：言辞。无传其溢言：不传达那些夸大失实的言辞。"},{id:"ji_hu_quan",term:"则几乎全",pinyin:"zé jī hū quán",meaning:"就差不多可以保全（自身）了。几乎：差不多；全：保全。"},{id:"qiao_douli2",term:"以巧斗力者",pinyin:"yǐ qiǎo dòu lì zhě",meaning:"用技巧来角力竞争的人。巧：技巧；斗力：角力、竞争。"},{id:"shi_yang2",term:"始乎阳",pinyin:"shǐ hū yáng",meaning:"开始时光明正大。阳：光明、公开、正大。"},{id:"zu_yin2",term:"卒乎阴",pinyin:"zú hū yīn",meaning:"最终走向阴暗（使用阴谋）。卒：最终；阴：阴暗、阴谋。始阳卒阴：开始光明，最终阴险，形容事态的恶化。"},{id:"zu_luan2",term:"卒乎乱",pinyin:"zú hū luàn",meaning:"最终走向混乱。卒：最终；乱：混乱失序。"},{id:"liang_chengxin2",term:"谅",pinyin:"liàng",meaning:"诚信、诚实。始乎谅：开始时出于诚信。"},{id:"bi_beilou2",term:"鄙",pinyin:"bǐ",meaning:"粗鄙、卑劣。常卒乎鄙：往往最终走向卑劣。"},{id:"jian_jiandan2",term:"简",pinyin:"jiǎn",meaning:"简单、简短。其作始也简：事情开始时简单。"},{id:"bi_wancheng",term:"毕",pinyin:"bì",meaning:"结束、完成。其将毕也：等到它将要结束的时候。"},{id:"ju_juda2",term:"巨",pinyin:"jù",meaning:"巨大、复杂。其将毕也必巨：到结束时必然变得复杂巨大（难以收拾）。"},{id:"xing_sangshi2",term:"行者，实丧也",pinyin:"xíng zhě shí sàng yě",meaning:"行动这件事，是实际损失的根源。行：行动、实际行为；实丧：实际的损失、丧失。"},{id:"fengbo_dong2",term:"风波易以动",pinyin:"fēng bō yì yǐ dòng",meaning:"言辞（风波）容易引起动荡。易以：容易因此；动：动荡、激起波澜。"},{id:"sangshi_wei2",term:"实丧易以危",pinyin:"shí sàng yì yǐ wēi",meaning:"实际损失容易导致危险。实丧：实际的损失；危：危险、危机。"},{id:"fen_wuyou2",term:"忿设无由",pinyin:"fèn shè wú yóu",meaning:"愤怒的产生往往没有来由（莫名而起）。忿：愤怒；设：产生、发生；无由：没有缘由。"},{id:"qiao_pianci2",term:"巧言偏辞",pinyin:"qiǎo yán piān cí",meaning:"巧妙的言辞往往偏颇失实。巧言：花言巧语；偏辞：偏颇的言辞。"},{id:"bu_ze_yin",term:"不择音",pinyin:"bù zé yīn",meaning:"不选择（发出什么）声音（乱叫）。择：选择；音：声音。兽临死时乱叫，不择声音，喻人在极端压力下失去理性。"},{id:"fu_ran",term:"茀然",pinyin:"fú rán",meaning:"急促喘息的样子。茀：通「怫」，郁结、急促；然：形容词词尾。【通假字】茀通「怫」，读 fú。"},{id:"bing_sheng_xinli",term:"并生心厉",pinyin:"bìng shēng xīn lì",meaning:"同时产生凶狠之心。并：同时；生：产生；心厉：凶狠、狠毒的心。"},{id:"ke_he_taizhi",term:"剋核太至",pinyin:"kè hé tài zhì",meaning:"苛刻追究到了极点。剋核：苛刻地追究、严厉地核查；太至：到了极点。"},{id:"buxiao_xin",term:"不肖之心",pinyin:"bù xiào zhī xīn",meaning:"不才、卑劣的心思（反应）。不肖：不才、卑劣；心：心理反应。"},{id:"ying_zhi",term:"应之",pinyin:"yìng zhī",meaning:"来回应它（苛刻的追究）。应：回应、应对；之：代词，指剋核太至的行为。"},{id:"zhong_jieguo",term:"终",pinyin:"zhōng",meaning:"结局、终点。孰知其所终：谁知道它（事情）的最终结局。"},{id:"wu_qian_ling",term:"无迁令",pinyin:"wú qiān lìng",meaning:"不要随意更改命令。迁：变更、改变；令：命令、指令。"},{id:"wu_quan_cheng",term:"无劝成",pinyin:"wú quàn chéng",meaning:"不要强求速成。劝：勉强、强求；成：完成、成功。"},{id:"guodu_yi",term:"过度益也",pinyin:"guò dù yì yě",meaning:"过度（行事）只会增加（祸患）。过度：超过限度；益：增加、更多。"},{id:"qian_quan_daishi",term:"迁令劝成殆事",pinyin:"qiān lìng quàn chéng dài shì",meaning:"随意更改命令、强求速成，都会危害事情。殆事：危害事情，殆：危害、危险。"},{id:"jiu_changqi",term:"久",pinyin:"jiǔ",meaning:"长久、时间积累。美成在久：好的成果需要长时间积累才能实现。"},{id:"bujigai",term:"不及改",pinyin:"bù jí gǎi",meaning:"来不及改正。不及：来不及；改：改正、纠正。恶成不及改：坏的结果一旦形成就来不及改正了。"},{id:"ke_bu_shen",term:"可不慎与",pinyin:"kě bù shèn yú",meaning:"能不谨慎吗？可：能、怎能；慎：谨慎；与：语气词，通「欤」，表反问。"},{id:"cheng_wu",term:"乘物",pinyin:"chéng wù",meaning:"顺应外物（的自然变化）。乘：顺应、驾驭；物：外物、事物。"},{id:"you_xin",term:"游心",pinyin:"yóu xīn",meaning:"让心神自由游走。游：自由游走；心：心神。乘物以游心：顺应外物来让心神自由——即不强求、不执着。"},{id:"tuo_budeyi",term:"托不得已",pinyin:"tuō bù dé yǐ",meaning:"寄托于不得不如此（的必然）。托：寄托、依托；不得已：无可奈何、不得不如此。"},{id:"yang_zhong",term:"养中",pinyin:"yǎng zhōng",meaning:"养护内心的中正。中：内心的中正平和；养中：涵养内心。托不得已以养中：寄托于必然之事来涵养内心的平和。"},{id:"zhi_yi",term:"至矣",pinyin:"zhì yǐ",meaning:"（这）是最高境界了。至：极致、最高；矣：语气词，表感叹。"},{id:"he_zuowei_bao",term:"何作为报也",pinyin:"hé zuò wéi bào yě",meaning:"何必刻意去做来求得回报呢？作为：刻意作为；报：回报、成效。"},{id:"mozuo_zhiming",term:"莫若为致命",pinyin:"mò ruò wéi zhì mìng",meaning:"不如顺从天命（尽力而为）。莫若：不如；致命：竭尽心力、听从天命；一说「传达（君主的）命令」。"},{id:"ci_qi_nan",term:"此其难者",pinyin:"cǐ qí nán zhě",meaning:"这才是其中最难的。此：这；其：其中；难者：困难之处。以「难」收束，呼应开篇叶公「甚栗之」的困境。"}],o=[{id:"yanhe_s1",label:"颜阖将傅卫灵公太子……吾奈之何",sentences:[[{text:"颜阖",glossary:"yanhe"},"将",{text:"傅",glossary:"fu_taishi"},{text:"卫灵公太子",glossary:"wei_taizi"},"，而问于",{text:"蘧伯玉",glossary:"qu_boyu"},"曰：「有人于此，",{text:"其德天杀",glossary:"de_tiansa"},"。"],[{text:"与之为无方",glossary:"wei_wufang"},"，则",{text:"危",glossary:"wei_weixian"},"吾国；与之为有方，则危吾身。"],["其知",{text:"适足以",glossary:"shi_zuyi"},"知人之过，而不知",{text:"其所以过",glossary:"suoyi_guo"},"。",{text:"若然者",glossary:"ruoran_zhe"},"，",{text:"吾奈之何",glossary:"nai_zhihe"},"？」"]]},{id:"yanhe_s2",label:"蘧伯玉曰善哉问乎……入于无疵",sentences:[["蘧伯玉曰：「",{text:"善哉问乎",glossary:"shanzai_wen"},"！",{text:"戒之",glossary:"jie_zhi"},"，",{text:"慎之",glossary:"shen_zhi"},"，",{text:"正女身也哉",glossary:"zheng_nvshen"},"！"],[{text:"形莫若就",glossary:"xing_mojuo_jiu"},"，",{text:"心莫若和",glossary:"xin_mojuo_he"},"。"],["虽然，",{text:"之二者有患",glossary:"zhi_er_huan"},"。",{text:"就不欲入",glossary:"jiu_bu_ru"},"，",{text:"和不欲出",glossary:"he_bu_chu"},"。"],[{text:"形就而入",glossary:"xing_jiu_ru"},"，且为",{text:"颠",glossary:"dian_diandao"},"为",{text:"灭",glossary:"mie_xiaomie"},"，为",{text:"崩",glossary:"beng_bengkui"},"为",{text:"蹶",glossary:"jue_shuaidao"},"。"],[{text:"心和而出",glossary:"xin_he_chu"},"，且为声为名，为",{text:"妖",glossary:"yao_yaonie"},"为",{text:"孽",glossary:"nie_zao孽"},"。"],["彼且为",{text:"婴儿",glossary:"ying_er"},"，亦与之为婴儿；彼且为",{text:"无町畦",glossary:"wu_tingqi"},"，亦与之为无町畦；彼且为",{text:"无崖",glossary:"wu_ya"},"，亦与之为无崖。"],[{text:"达之",glossary:"da_zhi"},"，",{text:"入于无疵",glossary:"ru_wuci"},"。」"]]},{id:"tanglanq_s1",label:"汝不知夫螳螂乎……几矣",sentences:[["「汝不知夫螳螂乎？",{text:"怒其臂",glossary:"nu_qi_bi"},"以",{text:"当",glossary:"dang_dangzhu"},"车辙，不知其不胜任也，是其才之美者也。"],[{text:"戒之",glossary:"jie_zhi"},"，",{text:"慎之",glossary:"shen_zhi"},"，",{text:"积伐而美者",glossary:"ji_fa_mei"},"以",{text:"犯之",glossary:"fan_zhi"},"，",{text:"几矣",glossary:"ji_yi_wei"},"！」"]]},{id:"yanghu_s1",label:"汝不知夫养虎者乎……故其杀者逆也",sentences:[["「汝不知夫养虎者乎？不敢以生物与之，为其",{text:"杀之之怒也",glossary:"sha_zhi_nu"},"；不敢以",{text:"全物",glossary:"quan_wu"},"与之，为其",{text:"决之之怒也",glossary:"jue_zhi_nu"},"。"],["时其饥饱，",{text:"达其怒心",glossary:"da_nu_xin"},"。"],["虎之与人异类而",{text:"媚养己者",glossary:"mei_yang_ji"},"，",{text:"顺也",glossary:"shun_ye2"},"；故",{text:"其杀者，逆也",glossary:"sha_ni_ye"},"。」"]]},{id:"yangma_s1",label:"夫爱马者……可不慎邪",sentences:[["「夫爱马者，",{text:"以筐盛矢",glossary:"kuang_sheng_shi"},"，",{text:"以蜄盛溺",glossary:"shen_sheng_ni"},"。"],["适有",{text:"蚊虻仆缘",glossary:"wenméng_puyan"},"，而",{text:"拊之不时",glossary:"fu_buzhi"},"，则",{text:"缺衔",glossary:"que_xian"},"，",{text:"毁首",glossary:"hui_shou"},"，",{text:"碎胸",glossary:"sui_xiong"},"。"],["意有所至而爱有所亡，可不",{text:"慎",glossary:"shen_jinshen"},"邪！」"]]}],d=[{id:"yanhe",term:"颜阖",pinyin:"yán hé",meaning:"人名，庄子寓言中的贤人，将要担任卫灵公太子的太傅，向蘧伯玉请教处世之道。"},{id:"fu_taishi",term:"傅",pinyin:"fù",meaning:"担任太傅、辅导（太子）。傅：太傅，辅导贵族子弟的老师；此处作动词，担任太傅。"},{id:"wei_taizi",term:"卫灵公太子",pinyin:"wèi líng gōng tài zǐ",meaning:"卫灵公的太子。卫灵公：卫国国君；太子：王位继承人。此太子品行暴戾，是本段困境的根源。"},{id:"qu_boyu",term:"蘧伯玉",pinyin:"qú bó yù",meaning:"卫国贤大夫，孔子曾称赞他「君子哉」。蘧：姓；伯玉：字。庄子借其口阐发处世智慧。"},{id:"de_tiansa",term:"其德天杀",pinyin:"qí dé tiān shā",meaning:"他的德行天生残暴刻薄。天杀：天生的残暴；杀：刻薄、残忍。【古今异义】杀：减损、刻薄，非「杀死」。"},{id:"wei_wufang",term:"与之为无方",pinyin:"yǔ zhī wéi wú fāng",meaning:"顺着他不加规范地相处。与之：与他；为无方：不按规矩、不加约束地相处；方：方法、规矩。"},{id:"wei_weixian",term:"危",pinyin:"wēi",meaning:"危害、使……危险。动词，使动用法。与之为无方则危吾国：不加规范则危害国家。"},{id:"shi_zuyi",term:"适足以",pinyin:"shì zú yǐ",meaning:"恰好足以、只够用来。适：恰好；足以：足够用来。其知适足以知人之过：他的智慧恰好只够用来发现别人的过失。"},{id:"suoyi_guo",term:"其所以过",pinyin:"qí suǒ yǐ guò",meaning:"自己犯过失的原因。所以过：犯过失的原因；其：自己。不知其所以过：不知道自己为何犯错。"},{id:"ruoran_zhe",term:"若然者",pinyin:"ruò rán zhě",meaning:"像这样的人。若然：像这样；者：的人。"},{id:"nai_zhihe",term:"吾奈之何",pinyin:"wú nài zhī hé",meaning:"我对他怎么办？奈之何：对他怎么办，奈……何：固定句式，表示「拿……怎么办」。"},{id:"shanzai_wen",term:"善哉问乎",pinyin:"shàn zāi wèn hū",meaning:"问得好啊！善哉：好啊，感叹词；问乎：这个问题啊。"},{id:"jie_zhi",term:"戒之",pinyin:"jiè zhī",meaning:"警戒它（这件事）、保持警惕。戒：警戒、戒备；之：代词，指与太子相处之事。"},{id:"shen_zhi",term:"慎之",pinyin:"shèn zhī",meaning:"谨慎对待它。慎：谨慎；之：代词。戒之·慎之：两字并列，反复强调警戒与谨慎。"},{id:"zheng_nvshen",term:"正女身也哉",pinyin:"zhèng rǔ shēn yě zāi",meaning:"端正你自身啊！正：端正；女：通「汝」，你；身：自身；也哉：感叹语气词。【通假字】女通「汝」。"},{id:"xing_mojuo_jiu",term:"形莫若就",pinyin:"xíng mò ruò jiù",meaning:"外在行为莫如顺就（他）。形：外在形态、行为举止；莫若：没有比……更好；就：顺从、靠近。"},{id:"xin_mojuo_he",term:"心莫若和",pinyin:"xīn mò ruò hé",meaning:"内心莫如保持平和。心：内心；和：平和、和顺。形就·心和：外顺内和，是与暴人相处的基本原则。"},{id:"zhi_er_huan",term:"之二者有患",pinyin:"zhī èr zhě yǒu huàn",meaning:"这两者（形就·心和）各有隐患。之：这；二者：两者；有患：有隐患、有危险。"},{id:"jiu_bu_ru",term:"就不欲入",pinyin:"jiù bù yù rù",meaning:"顺就（他）但不要陷入（其中）。就：顺从；不欲入：不要深陷进去、不要被同化。"},{id:"he_bu_chu",term:"和不欲出",pinyin:"hé bù yù chū",meaning:"平和（内心）但不要（将平和）外露。和：内心平和；不欲出：不要表露出来。"},{id:"xing_jiu_ru",term:"形就而入",pinyin:"xíng jiù ér rù",meaning:"外形顺就而（心也）陷入（其中）。就：顺从；入：深陷、被同化。"},{id:"dian_diandao",term:"颠",pinyin:"diān",meaning:"颠覆、倒塌。形就而入，且为颠为灭：外形顺就却深陷其中，将会导致颠覆。"},{id:"mie_xiaomie",term:"灭",pinyin:"miè",meaning:"消灭、覆灭。"},{id:"beng_bengkui",term:"崩",pinyin:"bēng",meaning:"崩溃、垮塌。"},{id:"jue_shuaidao",term:"蹶",pinyin:"jué",meaning:"跌倒、失败。颠·灭·崩·蹶四字并列，形容形就而入的种种灾祸。"},{id:"xin_he_chu",term:"心和而出",pinyin:"xīn hé ér chū",meaning:"内心平和却（将平和）外露。出：外露、表现出来。"},{id:"yao_yaonie",term:"妖",pinyin:"yāo",meaning:"妖异、招摇。心和而出，且为声为名，为妖为孽：内心平和却外露，将招致名声、妖异之祸。"},{id:"nie_zao孽",term:"孽",pinyin:"niè",meaning:"祸孽、灾祸。妖·孽并列，指因外露平和而招来的祸患。"},{id:"ying_er",term:"婴儿",pinyin:"yīng ér",meaning:"婴儿、幼儿。彼且为婴儿，亦与之为婴儿：他若像婴儿（任性无知），你也跟着像婴儿——即完全顺应对方的状态，不强加自己的判断。"},{id:"wu_tingqi",term:"无町畦",pinyin:"wú tīng qí",meaning:"没有界限、不分畛域。町畦：田间的界限、边界；无町畦：不设界限、无拘无束。彼且为无町畦：他若无拘无束，你也跟着无拘无束。"},{id:"wu_ya",term:"无崖",pinyin:"wú yá",meaning:"没有边际、无限放纵。崖：边际、界限；无崖：无边无际。三个「彼且为……亦与之为……」：婴儿→无町畦→无崖，层层递进，形容完全顺应对方。"},{id:"da_zhi",term:"达之",pinyin:"dá zhī",meaning:"通达地引导他（进入无疵的境界）。达：通达、引导；之：代词，指太子。"},{id:"ru_wuci",term:"入于无疵",pinyin:"rù yú wú cī",meaning:"进入没有过失的境界。无疵：没有瑕疵、没有过失。达之，入于无疵：通达地引导他，使他进入没有过失的境界——这是与暴人相处的最高目标。"},{id:"nu_qi_bi",term:"怒其臂",pinyin:"nù qí bì",meaning:"愤怒地举起（螳螂的）臂膀。怒：奋起、愤怒地；臂：螳螂的前臂。螳螂怒臂当车，喻以弱抗强、不自量力。"},{id:"dang_dangzhu",term:"当",pinyin:"dāng",meaning:"抵挡、阻挡。当车辙：挡住车轮的辙迹。⚠️ 读 dāng，非「应当」。"},{id:"ji_fa_mei",term:"积伐而美者",pinyin:"jī fá ér měi zhě",meaning:"积累自夸其才美的人。积伐：积累夸耀；美者：自认为才美之人。指颜阖若积累自夸，以才美去触犯太子。"},{id:"fan_zhi",term:"犯之",pinyin:"fàn zhī",meaning:"触犯他（太子）。犯：触犯、冒犯；之：代词，指太子。"},{id:"ji_yi_wei",term:"几矣",pinyin:"jī yǐ",meaning:"危险了！几：危险、接近（祸患）；矣：语气词，表感叹。【古今异义】几：危险，非「几乎」。"},{id:"sha_zhi_nu",term:"杀之之怒也",pinyin:"shā zhī zhī nù yě",meaning:"（激起老虎）因扑杀（猎物）而产生的怒性。杀之：扑杀猎物；之怒：由此产生的怒气。不敢以生物与之：不敢给老虎活的猎物，怕激起它扑杀的怒性。"},{id:"quan_wu",term:"全物",pinyin:"quán wù",meaning:"完整的（猎物）。全：完整；物：猎物、食物。不敢以全物与之：不敢给老虎完整的食物，怕激起它撕裂的怒性。"},{id:"jue_zhi_nu",term:"决之之怒也",pinyin:"jué zhī zhī nù yě",meaning:"（激起老虎）因撕裂（猎物）而产生的怒性。决：撕裂、分裂；之怒：由此产生的怒气。"},{id:"da_nu_xin",term:"达其怒心",pinyin:"dá qí nù xīn",meaning:"通达（顺应）它的怒性之心。达：通达、顺应；怒心：怒性、暴烈之心。时其饥饱，达其怒心：掌握它饥饱的时机，顺应它的怒性——喻与暴人相处须顺其性情。"},{id:"mei_yang_ji",term:"媚养己者",pinyin:"mèi yǎng jǐ zhě",meaning:"亲近豢养自己的人。媚：亲近、讨好；养己者：豢养自己的人。虎之与人异类而媚养己者：老虎与人类不同，却亲近豢养它的人。"},{id:"shun_ye2",term:"顺也",pinyin:"shùn yě",meaning:"是因为（养虎者）顺应了它（的本性）。顺：顺应；也：判断语气词。"},{id:"sha_ni_ye",term:"其杀者，逆也",pinyin:"qí shā zhě nì yě",meaning:"那些被（老虎）杀死的人，是因为违逆了它（的本性）。逆：违逆、违背；也：判断语气词。顺→媚，逆→杀，养虎之道即顺道之道。"},{id:"kuang_sheng_shi",term:"以筐盛矢",pinyin:"yǐ kuāng chéng shǐ",meaning:"用竹筐盛放马粪。筐：竹筐；盛：盛放、装；矢：通「屎」，粪便。【通假字】矢通「屎」。爱马者用筐盛粪，精心照料。"},{id:"shen_sheng_ni",term:"以蜄盛溺",pinyin:"yǐ shèn chéng nì",meaning:"用蛤蜊壳盛放马尿。蜄：大蛤蜊的壳；溺：尿液。【古今异义】溺：尿，非「溺水」。以筐盛矢·以蜄盛溺：两句并列，形容爱马者对马极为精心。"},{id:"wenméng_puyan",term:"蚊虻仆缘",pinyin:"wén méng pū yuán",meaning:"蚊子虻虫落在（马身上）爬行。蚊虻：蚊子和牛虻；仆缘：扑落爬行。"},{id:"fu_buzhi",term:"拊之不时",pinyin:"fǔ zhī bù shí",meaning:"拍打（马）不合时机。拊：拍打、轻拍；不时：不合时宜、时机不对。适有蚊虻仆缘，而拊之不时：恰好有蚊虻爬上马，却在不合时机时拍打它。"},{id:"que_xian",term:"缺衔",pinyin:"quē xián",meaning:"咬断嚼子（马嚼）。缺：损坏、咬断；衔：马嚼子，套在马嘴里的器具。"},{id:"hui_shou",term:"毁首",pinyin:"huǐ shǒu",meaning:"撞破头颅（马头套）。毁：损毁；首：头部，此处指头部的笼头。"},{id:"sui_xiong",term:"碎胸",pinyin:"suì xiōng",meaning:"踢碎胸部（马蹄踢人胸口）。碎：打碎、踢碎；胸：胸部。缺衔·毁首·碎胸三连：马受惊后的连锁反应，喻不合时机的「爱」反而招来祸患。"},{id:"shen_jinshen",term:"慎",pinyin:"shèn",meaning:"谨慎。可不慎邪：能不谨慎吗？呼应开篇「戒之，慎之」，首尾呼应。"}],u=[{id:"lishi_s1",label:"匠石之齐……行不辍何邪",sentences:[[{text:"匠石之齐",glossary:"jiangshi_zhi_qi"},"，",{text:"至乎曲辕",glossary:"zhi_quyuan"},"，见",{text:"栎社树",glossary:"li_she_shu"},"。"],["其",{text:"大蔽",glossary:"da_bi"},"数千牛，",{text:"絜之百围",glossary:"xie_baiwei"},"，其高临山，",{text:"十仞",glossary:"shi_ren"},{text:"而后有枝",glossary:"erhou_youzhi"},"，其",{text:"可以为舟者",glossary:"ke_wei_zhou"},{text:"旁十数",glossary:"pang_shishu"},"。"],[{text:"观者如市",glossary:"guan_rushi"},"，匠伯",{text:"不顾",glossary:"bu_gu"},"，",{text:"遂行不辍",glossary:"sui_xing_bucuo"},"。"],["弟子",{text:"厌观之",glossary:"yan_guanzhi"},"，走及匠石，曰：「自吾",{text:"执",glossary:"zhi_zhichi"},{text:"斧斤",glossary:"fu_jin"},"以",{text:"随",glossary:"sui_gensui"},"夫子，未尝见材如此其美也。先生不肯视，",{text:"行不辍",glossary:"xing_bucuo2"},"，何邪？」"]]},{id:"lishi_s2",label:"匠石曰已矣……故能若是之寿",sentences:[["匠石曰：「已矣，勿言之矣！",{text:"散木也",glossary:"san_mu"},"，以为舟则",{text:"沉",glossary:"chen_xia沉"},"，以为",{text:"棺椁",glossary:"guan_guo"},"则",{text:"速",glossary:"su_kuaisu"},{text:"腐",glossary:"fu_fuxiu"},"，以为",{text:"器",glossary:"qi_qiju"},"则",{text:"速毁",glossary:"su_hui"},"，"],["以为",{text:"门户",glossary:"men_hu"},"则",{text:"液樠",glossary:"ye_man"},"，以为",{text:"柱",glossary:"zhu_zhizi"},"则",{text:"蠹",glossary:"du_chongshi"},"，是",{text:"不材之木也",glossary:"bu_cai_mu"},"，无所可用，故",{text:"能若是之寿",glossary:"neng_ruoshi_shou"},"。」"]]},{id:"lishe_s1",label:"匠石归栎社见梦曰……又恶知散木",sentences:[["匠石归，",{text:"栎社",glossary:"li_she"},"见梦曰：「女",{text:"将恶乎比予哉",glossary:"jiang_ewu_bi"},"？若将比予于",{text:"文木",glossary:"wen_mu"},"邪？"],["夫",{text:"柤梨橘柚果蓏之属",glossary:"zha_li_guoluo"},"，",{text:"实熟则剥",glossary:"shi_shu_bo"},"，",{text:"剥则辱",glossary:"bo_ru"},"；",{text:"大枝折",glossary:"da_zhi_she"},"，",{text:"小枝泄",glossary:"xiao_zhi_xie"},"。"],[{text:"此以其能苦其生者也",glossary:"neng_ku_sheng"},"，故不终其天年而",{text:"中道夭",glossary:"zhongdao_yao"},"，",{text:"自掊击于世俗者也",glossary:"zi_pou_ji"},"。",{text:"物莫不若是",glossary:"wu_mo_rushi"},"。"],["且",{text:"予求无所可用",glossary:"yu_qiu_wuyong"},"久矣，几死，乃今得之，为",{text:"予大用",glossary:"yu_dayong"},"。"],["使",{text:"予也而有用",glossary:"yu_youyong"},"，且得有",{text:"此大也邪",glossary:"ci_da_ye"},"？"],["且也",{text:"若与予也皆物也",glossary:"ruo_yu_jiwu"},"，",{text:"奈何哉其相物也",glossary:"naihe_xiang_wu"},"！"],["而",{text:"几死之散人",glossary:"jisi_sanren"},"，又",{text:"恶知散木",glossary:"ewu_zhi_sanmu"},"！」"]]},{id:"lishe_s2",label:"匠石觉而诊其梦……有用且奈何",sentences:[["匠石",{text:"觉",glossary:"jue_xingwu"},"而",{text:"诊其梦",glossary:"zhen_qi_meng"},"。"],["弟子曰：「",{text:"趣取无用",glossary:"qu_wuyong"},"，则为",{text:"社矣",glossary:"she_yi"},"，",{text:"有用且奈何",glossary:"youyong_naihe"},"？」"]]},{id:"lishe_s3",label:"匠石曰密……不亦远乎",sentences:[["匠石曰：「",{text:"密",glossary:"mi_anjing"},"，",{text:"若无言",glossary:"ruo_wuyan"},"！"],[{text:"彼亦直寄焉",glossary:"bi_zhi_ji"},"，以为",{text:"不知己者诟厉也",glossary:"gou_li"},"。"],[{text:"不为社者",glossary:"bu_wei_she"},"，且",{text:"几有翦伐哉",glossary:"ji_jianfa"},"！"],["且也",{text:"彼其所保",glossary:"bi_suobao"},{text:"与众异",glossary:"yu_zhong_yi"},"，而以",{text:"义誉之",glossary:"yi_yu_zhi"},"，不亦远乎！」"]]}],l=[{id:"jiangshi_zhi_qi",term:"匠石之齐",pinyin:"jiàng shí zhī qí",meaning:"匠石前往齐国。匠石：木匠名石，庄子寓言人物；之：往、去，动词；齐：齐国。"},{id:"zhi_quyuan",term:"至乎曲辕",pinyin:"zhì hū qū yuán",meaning:"到达曲辕这个地方。曲辕：地名，在齐国境内；乎：于，介词。"},{id:"li_she_shu",term:"栎社树",pinyin:"lì shè shù",meaning:"作为土地神社树的栎树。栎：栎树，一种落叶乔木；社：土地神的祭祀场所；社树：社坛旁供奉的神树。"},{id:"da_bi",term:"大蔽",pinyin:"dà bì",meaning:"大到可以遮蔽（数千头牛）。蔽：遮蔽、遮盖。其大蔽数千牛：树冠之大可以遮蔽数千头牛。"},{id:"xie_baiwei",term:"絜之百围",pinyin:"xié zhī bǎi wéi",meaning:"测量它（树干）有百围之粗。絜：测量、度量，读 xié；围：两臂合抱为一围；百围：极言树干粗大。"},{id:"shi_ren",term:"十仞",pinyin:"shí rèn",meaning:"十仞高处。仞：古代长度单位，七尺或八尺为一仞；十仞：约七八十尺，极言树高。"},{id:"erhou_youzhi",term:"而后有枝",pinyin:"ér hòu yǒu zhī",meaning:"才开始有枝桠。而后：然后才；有枝：长出枝条。十仞而后有枝：高达十仞才开始分枝，极言主干之高直。"},{id:"ke_wei_zhou",term:"可以为舟者",pinyin:"kě yǐ wéi zhōu zhě",meaning:"可以用来做船的（枝干）。为舟：做成船；者：的（枝干）。"},{id:"pang_shishu",term:"旁十数",pinyin:"páng shí shù",meaning:"旁边有十几（棵同等大小的树那么多枝干）。旁：旁边、侧面；十数：十几，极言可用之材众多。"},{id:"guan_rushi",term:"观者如市",pinyin:"guān zhě rú shì",meaning:"观看的人多得像集市一样。如市：像集市，形容人多热闹。"},{id:"bu_gu",term:"不顾",pinyin:"bù gù",meaning:"不回头看、不理会。顾：回头看、顾及。匠伯不顾：匠石（匠伯）头也不回。"},{id:"sui_xing_bucuo",term:"遂行不辍",pinyin:"suì xíng bù chuò",meaning:"就这样走个不停。遂：就、于是；行：走；不辍：不停止，辍：停止。"},{id:"yan_guanzhi",term:"厌观之",pinyin:"yàn guān zhī",meaning:"看够了（才离开）追上匠石。厌：满足、看够；观之：观看它（栎社树）。【古今异义】厌：满足，非「厌恶」。"},{id:"zhi_zhichi",term:"执",pinyin:"zhí",meaning:"持、拿着。执斧斤：拿着斧头。"},{id:"fu_jin",term:"斧斤",pinyin:"fǔ jīn",meaning:"斧头。斧：大斧；斤：小斧。两字同义并列，泛指斧类工具。"},{id:"sui_gensui",term:"随",pinyin:"suí",meaning:"跟随、随从。以随夫子：来跟随先生（学艺）。"},{id:"xing_bucuo2",term:"行不辍",pinyin:"xíng bù chuò",meaning:"走个不停。与「遂行不辍」同，强调匠石对此树毫不在意。"},{id:"san_mu",term:"散木也",pinyin:"sàn mù yě",meaning:"（这是）无用的散材啊。散木：无用之木、散漫之材；也：判断语气词。散木是本篇核心概念，与「不材之木」互文。"},{id:"chen_xia沉",term:"沉",pinyin:"chén",meaning:"下沉。以为舟则沉：做成船就会沉没——木质不适合做船。"},{id:"guan_guo",term:"棺椁",pinyin:"guān guǒ",meaning:"棺材与外棺。棺：内棺；椁：套在棺外的外棺。以为棺椁则速腐：做成棺材就会很快腐烂。"},{id:"su_kuaisu",term:"速",pinyin:"sù",meaning:"很快、迅速。副词，修饰腐、毁等动词。"},{id:"fu_fuxiu",term:"腐",pinyin:"fǔ",meaning:"腐烂。以为棺椁则速腐：做棺材很快腐烂。"},{id:"qi_qiju",term:"器",pinyin:"qì",meaning:"器具、用具。以为器则速毁：做成器具很快损毁。"},{id:"su_hui",term:"速毁",pinyin:"sù huǐ",meaning:"很快损毁。速：迅速；毁：毁坏、损毁。"},{id:"men_hu",term:"门户",pinyin:"mén hù",meaning:"门板。门：大门；户：单扇门。以为门户则液樠：做成门板就会渗出树脂。"},{id:"ye_man",term:"液樠",pinyin:"yè mán",meaning:"渗出树脂（液汁外流）。液：液汁渗出；樠：树脂流出的样子。以为门户则液樠：做成门就会渗脂流液，无法使用。"},{id:"zhu_zhizi",term:"柱",pinyin:"zhù",meaning:"柱子。以为柱则蠹：做成柱子就会被虫蛀。"},{id:"du_chongshi",term:"蠹",pinyin:"dù",meaning:"被虫蛀蚀。蠹：蛀虫蚀木。以为柱则蠹：做柱子会被虫蛀。沉·腐·毁·液樠·蠹五种用途皆不可，极言散木之「无用」。"},{id:"bu_cai_mu",term:"不材之木也",pinyin:"bù cái zhī mù yě",meaning:"没有材用的木头。不材：没有材质可用；也：判断语气词。与「散木」互文，是匠石对栎社树的定性。"},{id:"neng_ruoshi_shou",term:"能若是之寿",pinyin:"néng ruò shì zhī shòu",meaning:"才能这样长寿。能：才能；若是：像这样；寿：长寿。无所可用，故能若是之寿：正因为无用，才能如此长寿——「无用之用」的核心命题。"},{id:"li_she",term:"栎社",pinyin:"lì shè",meaning:"栎社树（的神灵）。栎社：作为社神之树的栎树；此处指栎社树托梦给匠石。"},{id:"jiang_ewu_bi",term:"将恶乎比予哉",pinyin:"jiāng wū hū bǐ yǔ zāi",meaning:"你将要把我比作什么呢？将：将要；恶乎：何处、什么；比：比较、比拟；予：我；哉：疑问语气词。"},{id:"wen_mu",term:"文木",pinyin:"wén mù",meaning:"有纹理、有用的木材。文：纹理、有用；文木：有材质可用的树木，与「散木」对举。"},{id:"zha_li_guoluo",term:"柤梨橘柚果蓏之属",pinyin:"zhā lí jú yòu guǒ luǒ zhī shǔ",meaning:"山楂、梨、橘、柚等果树之类。柤：山楂；蓏：草本植物的果实（如瓜）；之属：之类。泛指一切有用的果树。"},{id:"shi_shu_bo",term:"实熟则剥",pinyin:"shí shú zé bō",meaning:"果实成熟就被剥取。实：果实；熟：成熟；剥：剥取、摘取。"},{id:"bo_ru",term:"剥则辱",pinyin:"bō zé rǔ",meaning:"被剥取就受到损辱（摧残）。辱：损辱、摧残。实熟则剥，剥则辱：果实成熟→被摘→受辱，有用反招祸。"},{id:"da_zhi_she",term:"大枝折",pinyin:"dà zhī shé",meaning:"大枝被折断。折：折断；读 shé。"},{id:"xiao_zhi_xie",term:"小枝泄",pinyin:"xiǎo zhī xiè",meaning:"小枝被扯落。泄：扯落、散落。大枝折·小枝泄：大小枝条皆因果实有用而遭摧残。"},{id:"neng_ku_sheng",term:"此以其能苦其生者也",pinyin:"cǐ yǐ qí néng kǔ qí shēng zhě yě",meaning:"这是因为它们的有用（才能）使自己的生命痛苦。以：因为；能：才能、有用；苦其生：使自己的生命痛苦。"},{id:"zhongdao_yao",term:"中道夭",pinyin:"zhōng dào yāo",meaning:"半途夭折。中道：中途、半路；夭：夭折、早死。不终其天年而中道夭：不能活完天赋的寿命而半途夭折。"},{id:"zi_pou_ji",term:"自掊击于世俗者也",pinyin:"zì pǒu jī yú shì sú zhě yě",meaning:"自己招来世俗的击打摧残。自：自己（招来）；掊击：击打、摧残，读 pǒu；于世俗：被世俗（人）。"},{id:"wu_mo_rushi",term:"物莫不若是",pinyin:"wù mò bù ruò shì",meaning:"万物没有不是这样的。莫不：没有不；若是：像这样。"},{id:"yu_qiu_wuyong",term:"予求无所可用",pinyin:"yǔ qiú wú suǒ kě yòng",meaning:"我（栎社）追求无所可用已经很久了。予：我；求：追求、寻求；无所可用：没有任何用处。"},{id:"yu_dayong",term:"予大用",pinyin:"yǔ dà yòng",meaning:"对我（来说）是最大的用处。予：对我；大用：最大的用处。几死，乃今得之，为予大用：差点死掉，如今才得到（无用），这对我是最大的用处——「无用之用，是为大用」。"},{id:"yu_youyong",term:"予也而有用",pinyin:"yǔ yě ér yǒu yòng",meaning:"我（栎社）如果有用的话。予也：我；而：如果；有用：有材用。"},{id:"ci_da_ye",term:"此大也邪",pinyin:"cǐ dà yě yé",meaning:"能有这样的（参天）大（树）吗？此大：这样的高大；也邪：反问语气，哪能……呢。使予也而有用，且得有此大也邪：如果我有用，还能长到这么大吗？"},{id:"ruo_yu_jiwu",term:"若与予也皆物也",pinyin:"ruò yǔ yǔ yě jiē wù yě",meaning:"你和我都是物（万物之一）啊。若：你；予：我；皆物：都是万物中的一员；也：语气词。"},{id:"naihe_xiang_wu",term:"奈何哉其相物也",pinyin:"nài hé zāi qí xiāng wù yě",meaning:"怎么能互相以「物」（有用无用）来评判对方呢？奈何：怎么；相物：互相以物的标准评判；也：语气词。"},{id:"jisi_sanren",term:"几死之散人",pinyin:"jī sǐ zhī sàn rén",meaning:"差点死掉的散漫之人（你匠石）。几死：差点死去；散人：散漫无用之人，此处反讽匠石——你自己才是「散人」。"},{id:"ewu_zhi_sanmu",term:"又恶知散木",pinyin:"yòu wū zhī sàn mù",meaning:"又怎么懂得散木（的道理）呢？恶知：怎么知道；散木：无用之木的道理。"},{id:"jue_xingwu",term:"觉",pinyin:"jué",meaning:"醒来、从梦中醒来。觉：睡醒；匠石觉：匠石从梦中醒来。"},{id:"zhen_qi_meng",term:"诊其梦",pinyin:"zhěn qí mèng",meaning:"思考（解析）那个梦。诊：诊察、思考分析；其梦：那个梦。"},{id:"qu_wuyong",term:"趣取无用",pinyin:"qù qǔ wú yòng",meaning:"一心追求无用（的境界）。趣：通「趋」，趋向、一心；取：取得、追求。【通假字】趣通「趋」。"},{id:"she_yi",term:"社矣",pinyin:"shè yǐ",meaning:"（就会）成为社树了。社：土地神社的神树；矣：语气词。趣取无用，则为社矣：一心追求无用，就变成社树了——弟子的反问，质疑「无用」是否可以刻意追求。"},{id:"youyong_naihe",term:"有用且奈何",pinyin:"yǒu yòng qiě nài hé",meaning:"（那么）有用的（树木）又该怎么办呢？且：那么、又；奈何：怎么办。"},{id:"mi_anjing",term:"密",pinyin:"mì",meaning:"住口、别说了。密：闭口、安静。【古今异义】非「秘密」，此处为感叹词，命令对方闭嘴。"},{id:"ruo_wuyan",term:"若无言",pinyin:"ruò wú yán",meaning:"你不要说话。若：你；无言：不要说话。密·若无言：两句并列，强调「不要多说」。"},{id:"bi_zhi_ji",term:"彼亦直寄焉",pinyin:"bǐ yì zhí jì yān",meaning:"那棵树不过是暂时寄身于此（社树之位）。彼：那棵树（栎社）；直：不过、只是；寄：寄托、暂居；焉：于此。"},{id:"gou_li",term:"不知己者诟厉也",pinyin:"bù zhī jǐ zhě gòu lì yě",meaning:"（那个梦）是对不了解自己的人的辱骂与责备。不知己者：不了解自己（栎社）的人，指匠石；诟厉：辱骂、责备；诟：辱骂；厉：严厉责备。"},{id:"bu_wei_she",term:"不为社者",pinyin:"bù wéi shè zhě",meaning:"（如果）不作为社树的话。不为社：不担任社树之职；者：假设连词，如果……的话。"},{id:"ji_jianfa",term:"几有翦伐哉",pinyin:"jī yǒu jiǎn fá zāi",meaning:"早就被砍伐了吧！几：早就、岂不；翦伐：砍伐、剪除；哉：感叹语气词。不为社者，且几有翦伐哉：若不是社树，早就被砍了——社树之名保护了它，但这不是栎社真正所保之道。"},{id:"bi_suobao",term:"彼其所保",pinyin:"bǐ qí suǒ bǎo",meaning:"那棵树（栎社）所保守的（道）。所保：所守护、所坚持的。"},{id:"yu_zhong_yi",term:"与众异",pinyin:"yǔ zhòng yì",meaning:"与众不同。众：众人、一般的树；异：不同。彼其所保与众异：栎社所坚守的道与众不同。"},{id:"yi_yu_zhi",term:"而以义誉之",pinyin:"ér yǐ yì yù zhī",meaning:"却用（世俗的）道义来称赞它。以义：用道义、用世俗标准；誉之：称赞它。而以义誉之，不亦远乎：用世俗道义来评价它，不是差得远了吗——世俗的「有用/无用」标准根本无法理解栎社的境界。"}],x=[{id:"ziqi_s1",label:"南伯子綦游乎商之丘……嗟乎神人以此不材",sentences:[[{text:"南伯子綦",glossary:"ziqi_ren"},"游乎",{text:"商之丘",glossary:"shang_qiu"},"，见大木焉，",{text:"有异",glossary:"you_yi"},"，",{text:"结驷千乘",glossary:"jie_si_qian"},"，",{text:"隐",glossary:"yin_yincang"},"将",{text:"芘其所藾",glossary:"bi_suo_lai"},"。"],["子綦曰：「此何木也哉？此必有",{text:"异材",glossary:"yi_cai"},"夫！」"],["仰而视其细枝，则",{text:"拳曲",glossary:"quan_qu"},"而不可以为",{text:"栋梁",glossary:"dong_liang"},"；"],["俯而视其大根，则",{text:"轴解",glossary:"zhou_jie"},"而不可以为",{text:"棺椁",glossary:"guan_guo2"},"；"],[{text:"咶其叶",glossary:"gua_ye"},"，则口烂而为伤；",{text:"嗅之",glossary:"xiu_zhi"},"，则使人",{text:"狂酲",glossary:"kuang_cheng"},"，三日而不已。"],["子綦曰：「此",{text:"果",glossary:"guo_queshi"},"不材之木也，以至于此其大也。",{text:"嗟乎神人",glossary:"jie_shenren"},"，",{text:"以此不材",glossary:"yi_ci_bucai"},"！」"]]},{id:"jingshi_s1",label:"宋有荆氏者……此其以材伤也",sentences:[["宋有",{text:"荆氏者",glossary:"jing_shi"},"，",{text:"宜楸柏桑",glossary:"yi_qiu_bai_sang"},"。"],[{text:"其拱把而上者",glossary:"gong_ba_shang"},"，",{text:"求",glossary:"qiu_xuyao"},{text:"狙猴之杙者",glossary:"ju_hou_yi"},{text:"斩之",glossary:"zhan_zhi"},"；"],["三围四围，求高名之",{text:"丽者",glossary:"li_zhe"},{text:"斩之",glossary:"zhan_zhi"},"；"],["七围八围，贵人富家求",{text:"椫为轮者",glossary:"shan_wei_lun"},{text:"斩之",glossary:"zhan_zhi"},"；"],["十围，求",{text:"桁杨者",glossary:"heng_yang"},{text:"斩之",glossary:"zhan_zhi"},"。"],["此皆以其材之",{text:"患也",glossary:"cai_huan"},"，故未终其天年而中道之夭。"],["不择地而生，此其以",{text:"材伤也",glossary:"cai_shang"},"。"],[{text:"桀纣之暴",glossary:"jie_zhou_bao"},"，",{text:"汤武之战",glossary:"tang_wu_zhan"},"，皆以",{text:"材伤也",glossary:"cai_shang"},"。"]]},{id:"wuzhu_s1",label:"故解之以牛之白颡者……此乃神人之所以为大祥也",sentences:[["故解之以",{text:"牛之白颡者",glossary:"bai_sang"},"与",{text:"豚之亢鼻者",glossary:"kang_bi"},"与人有",{text:"痔疾者",glossary:"zhi_ji"},"，不可以",{text:"适河",glossary:"shi_he"},"。"],["此皆",{text:"巫祝",glossary:"wu_zhu"},"以知之矣，所以为",{text:"不祥也",glossary:"bu_xiang"},"。"],["此乃神人之所以为",{text:"大祥也",glossary:"da_xiang"},"。"]]}],p=[{id:"ziqi_ren",term:"南伯子綦",pinyin:"nán bó zǐ qí",meaning:"人名，庄子寓言中的得道者。南伯：封号或称谓；子綦：名。《齐物论》中亦出现此人，以「吾丧我」著称。"},{id:"shang_qiu",term:"商之丘",pinyin:"shāng zhī qiū",meaning:"商丘，地名，宋国的都城所在地。商：商朝故地；丘：土丘、高地。"},{id:"you_yi",term:"有异",pinyin:"yǒu yì",meaning:"（形态）与众不同、有奇异之处。异：奇异、异常。"},{id:"jie_si_qian",term:"结驷千乘",pinyin:"jié sì qiān shèng",meaning:"可以停放千辆四马驾的车队（在树荫下）。结驷：四匹马拉的车队；千乘：千辆车；极言树冠之广大。"},{id:"yin_yincang",term:"隐",pinyin:"yǐn",meaning:"遮蔽、隐蔽。隐将芘其所藾：遮蔽将要庇护它所荫蔽的地方。"},{id:"bi_suo_lai",term:"芘其所藾",pinyin:"pì qí suǒ lài",meaning:"庇护（遮蔽）它所荫蔽的范围。芘：通「庇」，庇护、遮蔽；藾：荫蔽、遮盖。【通假字】芘通「庇」，读 pì。"},{id:"yi_cai",term:"异材",pinyin:"yì cái",meaning:"奇异的材质、特殊的才能。异：奇异；材：材质、才能。子綦初见大木，以为必有异材——后文证明恰恰相反。"},{id:"quan_qu",term:"拳曲",pinyin:"quán qū",meaning:"弯曲蜷缩。拳：弯曲如拳；曲：弯曲。细枝拳曲，不可为栋梁。"},{id:"dong_liang",term:"栋梁",pinyin:"dòng liáng",meaning:"屋顶的主梁。栋：屋脊正梁；梁：横梁。不可以为栋梁：不能用作建筑的主梁。"},{id:"zhou_jie",term:"轴解",pinyin:"zhóu jiě",meaning:"（木质）松散分裂。轴：木质的纹理轴心；解：分裂、散开。大根轴解，不可为棺椁。"},{id:"guan_guo2",term:"棺椁",pinyin:"guān guǒ",meaning:"棺材与外棺。棺：内棺；椁：套在棺外的外棺。与第四段「匠石」篇同词，呼应「散木」主题。"},{id:"gua_ye",term:"咶其叶",pinyin:"guā qí yè",meaning:"舔舐它的叶子。咶：舔、以舌舐；读 guā。【古今异义】咶：舔，非常用字。"},{id:"xiu_zhi",term:"嗅之",pinyin:"xiù zhī",meaning:"闻它（的气味）。嗅：用鼻子闻；之：代词，指大木。"},{id:"kuang_cheng",term:"狂酲",pinyin:"kuáng chéng",meaning:"发狂如醉。狂：发狂；酲：醉后神志不清，读 chéng。使人狂酲，三日而不已：让人发狂如醉，三天都不能停止。"},{id:"guo_queshi",term:"果",pinyin:"guǒ",meaning:"果然、确实。副词，表证实。此果不材之木也：这果然是无用之木。"},{id:"jie_shenren",term:"嗟乎神人",pinyin:"jiē hū shén rén",meaning:"唉，神人啊！嗟乎：感叹词，唉；神人：得道的神妙之人。子綦感叹神人正是凭借「不材」而成就其神妙。"},{id:"yi_ci_bucai",term:"以此不材",pinyin:"yǐ cǐ bù cái",meaning:"凭借这（无用）的不材（而成就自身）。以：凭借；此：这（无用之道）；不材：无材可用。呼应第四段「无用之用，是为大用」。"},{id:"jing_shi",term:"荆氏者",pinyin:"jīng shì zhě",meaning:"荆氏这个地方。荆氏：宋国的一个地名；者：表停顿。宋有荆氏者：宋国有个叫荆氏的地方。"},{id:"yi_qiu_bai_sang",term:"宜楸柏桑",pinyin:"yí qiū bǎi sāng",meaning:"适宜种植楸树、柏树、桑树。宜：适宜、适合；楸：楸树；柏：柏树；桑：桑树。三种皆为有用之材。"},{id:"gong_ba_shang",term:"其拱把而上者",pinyin:"qí gǒng bǎ ér shàng zhě",meaning:"那些长到一两手合围以上粗细的（树）。拱：两手合围；把：一手握住；拱把而上：达到一两手合围以上的粗细。"},{id:"qiu_xuyao",term:"求",pinyin:"qiú",meaning:"需要、寻求。此处指有人需要某种用途而来砍伐。"},{id:"ju_hou_yi",term:"狙猴之杙者",pinyin:"jū hóu zhī yì zhě",meaning:"寻找拴猴子的木桩的人。狙猴：猴子；杙：小木桩、系绳的桩；读 yì。求狙猴之杙者斩之：有人要找拴猴的木桩，就来砍它。"},{id:"zhan_zhi",term:"斩之",pinyin:"zhǎn zhī",meaning:"砍伐它。斩：砍断；之：代词，指那棵树。四个「斩之」反复出现，强调有用之树被砍伐的命运。"},{id:"li_zhe",term:"丽者",pinyin:"lì zhě",meaning:"栋梁之材（高大华美的木材）。丽：通「栭」，栋梁；一说「丽」为华美高大之材。求高名之丽者：寻求用作高大建筑栋梁的人。"},{id:"shan_wei_lun",term:"椫为轮者",pinyin:"shàn wéi lún zhě",meaning:"用来做车轮的（坚硬木材）。椫：坚硬的木材，适合做车轮；读 shàn；为轮：做成车轮。"},{id:"heng_yang",term:"桁杨者",pinyin:"héng yáng zhě",meaning:"用来做刑具（枷锁）的（大木）。桁杨：古代套在囚犯颈部或脚部的木制刑具；读 héng yáng。求桁杨者：寻找做刑具用的大木。"},{id:"cai_huan",term:"患也",pinyin:"huàn yě",meaning:"（材质带来的）祸患。此皆以其材之患也：这些（被砍伐）都是因为它们材质（有用）带来的祸患。"},{id:"cai_shang",term:"材伤也",pinyin:"cái shāng yě",meaning:"因材质（有用）而受伤害。材：材质、才能；伤：伤害、损伤。此其以材伤也：这是因为（树木）有用的材质而遭受伤害。"},{id:"jie_zhou_bao",term:"桀纣之暴",pinyin:"jié zhòu zhī bào",meaning:"夏桀、商纣的暴虐（之才）。桀纣：夏桀与商纣，古代暴君；暴：暴虐之才能。桀纣以暴虐之「材」（才）而招来覆灭之祸。"},{id:"tang_wu_zhan",term:"汤武之战",pinyin:"tāng wǔ zhī zhàn",meaning:"商汤、周武王的征战（之才）。汤：商汤；武：周武王；战：征战之才。汤武以征战之「材」（才）而招来战争之患。桀纣·汤武并举：暴君与圣王皆因「材」（才能）而受伤，说明「以材伤」是普遍规律。"},{id:"bai_sang",term:"牛之白颡者",pinyin:"niú zhī bái sǎng zhě",meaning:"额头白色的牛。白颡：白色额头；颡：额头，读 sǎng。白额牛在古代被视为不祥之物，不可用于祭祀河神。"},{id:"kang_bi",term:"豚之亢鼻者",pinyin:"tún zhī kàng bí zhě",meaning:"鼻子朝天的猪。豚：小猪；亢鼻：鼻孔朝上、仰鼻；读 kàng bí。亢鼻猪亦被视为不祥，不可用于祭祀。"},{id:"zhi_ji",term:"痔疾者",pinyin:"zhì jí zhě",meaning:"患有痔疮的人。痔疾：痔疮；者：的人。患痔疾者被视为不洁，不可参与祭河之礼。"},{id:"shi_he",term:"适河",pinyin:"shì hé",meaning:"前往（祭祀）河神。适：前往；河：黄河，古代重要的祭祀对象。不可以适河：不可以用来祭祀河神（因被视为不祥）。"},{id:"wu_zhu",term:"巫祝",pinyin:"wū zhù",meaning:"巫师与祝官。巫：巫师，主持祭祀；祝：祝官，掌管祭祀祷告。此皆巫祝以知之矣：这些（不祥之物）都是巫祝所知道的。"},{id:"bu_xiang",term:"不祥也",pinyin:"bù xiáng yě",meaning:"不吉祥的（东西）。不祥：不吉利；也：判断语气词。巫祝认为白颡牛、亢鼻猪、痔疾者皆为不祥，不可祭河。"},{id:"da_xiang",term:"大祥也",pinyin:"dà xiáng yě",meaning:"最大的吉祥。大祥：最大的吉祥；也：判断语气词。此乃神人之所以为大祥也：这（被世俗视为不祥的「无用」）正是神人之所以获得最大吉祥的原因。不祥→大祥：世俗的「不祥」在神人眼中恰是「大祥」，与「无用之用」互文，点明全篇主旨。"}],z=[{id:"zhili_s1",label:"支离疏者……两髀为胁",sentences:[[{text:"支离疏者",glossary:"zhili_shu"},"，",{text:"颐隐于脐",glossary:"yi_yin_qi"},"，肩高于顶，",{text:"会撮指天",glossary:"hui_cuo_tian"},"，",{text:"五管在上",glossary:"wu_guan"},"，",{text:"两髀为胁",glossary:"liang_bi_xie"},"。"]]},{id:"zhili_s2",label:"挫针治繲……足以食十人",sentences:[[{text:"挫针治繲",glossary:"cuo_zhen_xie"},"，",{text:"足以糊口",glossary:"zu_hukou"},"；",{text:"鼓筴播精",glossary:"gu_ce_bo_jing"},"，",{text:"足以食十人",glossary:"zu_shi_shiren"},"。"]]},{id:"zhili_s3",label:"上征武士……则受三钟与十束薪",sentences:[["上征武士，则",{text:"支离",glossary:"zhili_mianyi"},{text:"攘臂",glossary:"rang_bi"},"而游于其间；"],["上有大役，则支离",{text:"以",glossary:"yi_pingjie"},{text:"有常疾",glossary:"you_changjie"},{text:"不受功",glossary:"bu_shou_gong"},"；"],["上",{text:"与",glossary:"yu_gei"},{text:"病者粟",glossary:"bingzhe_su"},"，则受",{text:"三钟",glossary:"san_zhong"},"与",{text:"十束薪",glossary:"shi_shu_xin"},"。"]]},{id:"zhili_s4",label:"夫支离其形者……又况支离其德者乎",sentences:[["夫",{text:"支离其形者",glossary:"zhili_qi_xing"},"，犹足以养其身，终其天年，又",{text:"况",glossary:"kuang_hekuang"},{text:"支离其德者乎",glossary:"zhili_qi_de"},"！"]]}],b=[{id:"zhili_shu",term:"支离疏者",pinyin:"zhī lí shū zhě",meaning:"名叫支离疏的人。支离：肢体残缺、散乱；疏：名字。支离疏：庄子虚构的残疾人，以形残而德全为寓意。"},{id:"yi_yin_qi",term:"颐隐于脐",pinyin:"yí yǐn yú qí",meaning:"下巴藏在肚脐里（脊背严重弯曲）。颐：下巴；隐：隐藏、陷入；脐：肚脐。极言其脊背弯曲之甚，下巴几乎触及肚脐。"},{id:"hui_cuo_tian",term:"会撮指天",pinyin:"huì cuō zhǐ tiān",meaning:"发髻朝向天空。会撮：发髻、头顶的发结；指天：朝向天空。因脊背弯曲，头顶反而朝上指天。"},{id:"wu_guan",term:"五管在上",pinyin:"wǔ guǎn zài shàng",meaning:"五脏（的位置）都在（背部）上方。五管：五脏，心肝脾肺肾；在上：位于上方（因弯曲而内脏位置异常）。"},{id:"liang_bi_xie",term:"两髀为胁",pinyin:"liǎng bì wéi xié",meaning:"两条大腿与肋骨并列（大腿高过胁部）。髀：大腿；胁：肋骨、胁部。两髀为胁：大腿抬至与胁部齐平，极言其形体扭曲之甚。颐隐于脐·会撮指天·五管在上·两髀为胁：四句并列，描绘支离疏极度残缺的形体。"},{id:"cuo_zhen_xie",term:"挫针治繲",pinyin:"cuò zhēn zhì xiè",meaning:"（用手）搓线穿针、缝补衣物。挫针：搓线穿针；治繲：缝补破衣；繲：破旧的衣物，读 xiè。形残之人仍能以手工维持生计。"},{id:"zu_hukou",term:"足以糊口",pinyin:"zú yǐ hú kǒu",meaning:"足够维持生活（糊口）。足以：足够用来；糊口：勉强维持口食。"},{id:"gu_ce_bo_jing",term:"鼓筴播精",pinyin:"gǔ cè bō jīng",meaning:"摇动簸箕筛选米粮。鼓：摇动、振动；筴：簸箕，读 cè；播：扬、筛；精：精米、细粮。"},{id:"zu_shi_shiren",term:"足以食十人",pinyin:"zú yǐ shí shí rén",meaning:"足够养活十个人。食：养活、供养，读 sì；十人：十个人。挫针糊口·鼓筴食十人：形残之人自养有余，甚至可养活他人。"},{id:"zhili_mianyi",term:"支离",pinyin:"zhī lí",meaning:"支离疏（因形残）得以免除（征役）。此处作动词性理解，指支离疏凭借残缺之形而自由游走于征兵之间，不被征用。"},{id:"rang_bi",term:"攘臂",pinyin:"rǎng bì",meaning:"挥动手臂、自由走动。攘：挥动、伸展；臂：手臂。上征武士，则支离攘臂而游于其间：朝廷征兵，支离疏却可以挥着手臂在其中自由走动（因残疾而不被征召）。"},{id:"yi_pingjie",term:"以",pinyin:"yǐ",meaning:"凭借、因为。介词，表凭借原因。以有常疾：凭借有长期疾病（而免役）。"},{id:"you_changjie",term:"有常疾",pinyin:"yǒu cháng jí",meaning:"有长期的疾病（残疾）。常疾：长期疾患、慢性残疾。"},{id:"bu_shou_gong",term:"不受功",pinyin:"bù shòu gōng",meaning:"不被分派劳役（任务）。受功：接受劳役任务；不受功：免除劳役。上有大役，则支离以有常疾不受功：朝廷有大型徭役，支离疏凭残疾而免除。"},{id:"yu_gei",term:"与",pinyin:"yǔ",meaning:"给予、发放。上与病者粟：朝廷给患病者发放粮食。"},{id:"bingzhe_su",term:"病者粟",pinyin:"bìng zhě sù",meaning:"（发放给）患病者的粮食。病者：患病之人；粟：粮食、小米。"},{id:"san_zhong",term:"三钟",pinyin:"sān zhōng",meaning:"三钟粮食。钟：古代容量单位，六斛四斗为一钟；三钟：数量相当可观。"},{id:"shi_shu_xin",term:"十束薪",pinyin:"shí shù xīn",meaning:"十捆柴薪。束：捆；薪：柴火。三钟粟与十束薪：朝廷救济残疾者，支离疏因残而受惠。上征武士·上有大役·上与病者粟：三个「上」字句，层层递进，形残反而三度得益。"},{id:"zhili_qi_xing",term:"支离其形者",pinyin:"zhī lí qí xíng zhě",meaning:"形体残缺的人。支离其形：形体散乱残缺；者：的人。"},{id:"kuang_hekuang",term:"况",pinyin:"kuàng",meaning:"何况、更何况。副词，表递进。又况……乎：又何况……呢。"},{id:"zhili_qi_de",term:"支离其德者乎",pinyin:"zhī lí qí dé zhě hū",meaning:"（那些）使德行残缺（散漫无用）的人呢！支离其德：使德行散漫、不拘于世俗规范；者：的人；乎：感叹语气词。支离其形→犹足以养身终年；支离其德→更能超越世俗束缚。「支离其德」是本篇点睛之笔，与「无用之用」「散木」主题一脉相承。"}],q=[{id:"jieyu_s1",label:"孔子适楚……何如德之衰也",sentences:[["孔子",{text:"适楚",glossary:"shi_chu"},"，楚狂",{text:"接舆",glossary:"jie_yu"},"游其门曰：「",{text:"凤兮凤兮",glossary:"feng_xi"},"，",{text:"何如",glossary:"he_ru"},{text:"德之衰也",glossary:"de_shuai"},"！"]]},{id:"jieyu_s2",label:"来世不可待……圣人生焉",sentences:[[{text:"来世不可待",glossary:"laishi_buke_dai"},"，",{text:"往世不可追也",glossary:"wangshi_buke_zhui"},"。"],["天下有道，圣人",{text:"成焉",glossary:"cheng_yan"},"；天下无道，圣人",{text:"生焉",glossary:"sheng_yan"},"。"]]},{id:"jieyu_s3",label:"方今之时仅免刑焉……莫之知避",sentences:[["方今之时，",{text:"仅",glossary:"jin_jin"},{text:"免刑焉",glossary:"mian_xing"},"。"],[{text:"福轻乎羽",glossary:"fu_qing_yu"},"，",{text:"莫之知载",glossary:"mo_zhi_zai"},"；"],[{text:"祸重乎地",glossary:"huo_zhong_di"},"，",{text:"莫之知避",glossary:"mo_zhi_bi"},"。"]]},{id:"jieyu_s4",label:"已乎已乎……无伤吾足",sentences:[[{text:"已乎已乎",glossary:"yi_hu_yi"},"，",{text:"临人以德",glossary:"lin_ren_de"},"！"],[{text:"殆乎殆乎",glossary:"dai_hu_dai"},"，",{text:"画地而趋",glossary:"hua_di_qu"},"！"],[{text:"迷阳迷阳",glossary:"mi_yang"},"，",{text:"无伤吾行",glossary:"wu_shang_xing"},"！",{text:"吾行却曲",glossary:"xing_que_qu"},"，",{text:"无伤吾足",glossary:"wu_shang_zu"},"！」"]]},{id:"shanmu_s1",label:"山木自寇也……无用之用也",sentences:[[{text:"山木自寇也",glossary:"shanmu_kou"},"，",{text:"膏火自煎也",glossary:"gaohuo_jian"},"。"],[{text:"桂可食，故伐之",glossary:"gui_fa"},"；",{text:"漆可用，故割之",glossary:"qi_ge"},"。"],["人皆知",{text:"有用之用",glossary:"youyong_yong"},"，而莫知",{text:"无用之用也",glossary:"wuyong_yong"},"。"]]}],w=[{id:"shi_chu",term:"适楚",pinyin:"shì chǔ",meaning:"前往楚国。适：前往、去；楚：楚国。"},{id:"jie_yu",term:"接舆",pinyin:"jiē yú",meaning:"楚国的狂人，隐士。接舆：人名，以佯狂避世著称，《论语》中亦有记载。楚狂接舆：楚国的狂人接舆，「狂」非真狂，而是以狂态处世、远离仕途的隐者。"},{id:"feng_xi",term:"凤兮凤兮",pinyin:"fèng xī fèng xī",meaning:"凤凰啊凤凰啊！以凤凰比喻孔子——凤凰是有德之鸟，只在天下有道时出现；接舆以此暗讽孔子在乱世中奔走，有德却无处施展。"},{id:"he_ru",term:"何如",pinyin:"hé rú",meaning:"怎么这样、为何如此。疑问副词，表感叹式追问。"},{id:"de_shuai",term:"德之衰也",pinyin:"dé zhī shuāi yě",meaning:"（你的）德行（竟）衰落至此啊！衰：衰落、衰退；也：感叹语气词。凤兮凤兮，何如德之衰也：凤凰啊凤凰，你的德行怎么衰落成这样——讽刺孔子在乱世中仍奔走求仕，有失高洁。"},{id:"laishi_buke_dai",term:"来世不可待",pinyin:"lái shì bù kě dài",meaning:"未来的世道不可等待（指望）。来世：未来的世代；待：等待、期待。"},{id:"wangshi_buke_zhui",term:"往世不可追也",pinyin:"wǎng shì bù kě zhuī yě",meaning:"过去的世道不可追回。往世：过去的世代；追：追回、挽回；也：语气词。来世不可待·往世不可追：前后皆不可为，唯有顺应当下——暗示孔子奔走无益。"},{id:"cheng_yan",term:"成焉",pinyin:"chéng yān",meaning:"（在其中）成就功业。成：成就、有所作为；焉：于此，兼词。天下有道，圣人成焉：天下有道时，圣人可以成就事业。"},{id:"sheng_yan",term:"生焉",pinyin:"shēng yān",meaning:"（在其中）保全生命（即可）。生：活着、保全生命；焉：于此。天下无道，圣人生焉：天下无道时，圣人只求保全生命。成焉·生焉对举：有道则进，无道则退——孔子在无道之世仍求「成」，故接舆以为德衰。"},{id:"jin_jin",term:"仅",pinyin:"jǐn",meaning:"仅仅、只能。副词，表勉强。方今之时，仅免刑焉：如今这个时代，（圣人）仅仅能免于刑罚罢了。"},{id:"mian_xing",term:"免刑焉",pinyin:"miǎn xíng yān",meaning:"免于刑罚。免：免除；刑：刑罚；焉：语气词。仅免刑焉：只能勉强免于刑罚，极言乱世之险。"},{id:"fu_qing_yu",term:"福轻乎羽",pinyin:"fú qīng hū yǔ",meaning:"福气比羽毛还轻。轻乎：比……轻；羽：羽毛。喻福气虽轻易可得，却无人知道如何承载。"},{id:"mo_zhi_zai",term:"莫之知载",pinyin:"mò zhī zhī zài",meaning:"没有人知道如何承载（它）。莫：没有人；之：代词，指福；知载：知道如何承载。【宾语前置】莫之知载=莫知载之。"},{id:"huo_zhong_di",term:"祸重乎地",pinyin:"huò zhòng hū dì",meaning:"祸患比大地还重。重乎：比……重；地：大地。喻祸患虽沉重，却无人知道如何躲避。"},{id:"mo_zhi_bi",term:"莫之知避",pinyin:"mò zhī zhī bì",meaning:"没有人知道如何躲避（它）。莫：没有人；避：躲避。【宾语前置】莫之知避=莫知避之。福轻莫知载·祸重莫知避：对举，形容世人对福祸皆茫然无知。"},{id:"yi_hu_yi",term:"已乎已乎",pinyin:"yǐ hū yǐ hū",meaning:"算了吧算了吧！已：停止、罢了；乎：语气词，表感叹。反复叠用，强烈劝阻孔子放弃以德教化他人。"},{id:"lin_ren_de",term:"临人以德",pinyin:"lín rén yǐ dé",meaning:"用德行来教化（居高临下地对待）他人。临：居高临下、面对；以德：凭借德行。已乎已乎，临人以德：算了吧，不要再用德行去教化别人了——讽刺孔子以德自居、强行教化。"},{id:"dai_hu_dai",term:"殆乎殆乎",pinyin:"dài hū dài hū",meaning:"危险啊危险啊！殆：危险；乎：感叹语气词。反复叠用，警示孔子在乱世中奔走的危险。"},{id:"hua_di_qu",term:"画地而趋",pinyin:"huà dì ér qū",meaning:"在地上画出界限（规范）而奔走其中。画地：在地上划定界限；趋：奔走、急行。喻孔子以礼义划定规范，在其中奔走——接舆讽其自设樊笼。"},{id:"mi_yang",term:"迷阳迷阳",pinyin:"mí yáng mí yáng",meaning:"荆棘啊荆棘！迷阳：有刺的荆棘植物。反复叠呼，像在呼唤荆棘，实为比喻乱世中的种种险阻。"},{id:"wu_shang_xing",term:"无伤吾行",pinyin:"wú shāng wú xíng",meaning:"不要伤害我的行走。无：不要；伤：伤害；吾行：我的行走、我的路。"},{id:"xing_que_qu",term:"吾行却曲",pinyin:"wú xíng què qū",meaning:"我的行走迂回曲折（绕道而行）。却曲：退却迂回、弯曲绕行。迷阳迷阳，无伤吾行；吾行却曲，无伤吾足：荆棘啊，不要伤我，我会绕道而行，不伤我的脚——喻处世应懂得迂回避让，不与险阻硬碰。"},{id:"wu_shang_zu",term:"无伤吾足",pinyin:"wú shāng wú zú",meaning:"不要伤害我的脚。无：不要；伤：伤害；吾足：我的脚。与「无伤吾行」对举，强调迂回避让之道。"},{id:"shanmu_kou",term:"山木自寇也",pinyin:"shān mù zì kòu yě",meaning:"山上的树木（因有用）自己招来砍伐。自寇：自己招来侵害；寇：侵害、砍伐；也：判断语气词。"},{id:"gaohuo_jian",term:"膏火自煎也",pinyin:"gāo huǒ zì jiān yě",meaning:"油脂（因可燃）自己招来燃烧煎熬。膏：油脂；火：燃火；自煎：自己煎熬自己；也：语气词。山木自寇·膏火自煎：两句对举，皆喻「以材伤」——有用之物因其用而自招祸患。"},{id:"gui_fa",term:"桂可食，故伐之",pinyin:"guì kě shí gù fá zhī",meaning:"桂树因为可以食用，所以被砍伐。桂：桂树，树皮可入药食用；故：所以；伐：砍伐。"},{id:"qi_ge",term:"漆可用，故割之",pinyin:"qī kě yòng gù gē zhī",meaning:"漆树因为可以使用（割取漆液），所以被割取。漆：漆树，可割取漆液；割：割取、切割。桂可食故伐·漆可用故割：两句对举，呼应「以材伤」主题，有用即招祸。"},{id:"youyong_yong",term:"有用之用",pinyin:"yǒu yòng zhī yòng",meaning:"有用之物的用处（世俗所知的用途）。有用：有实际用途；之用：的用处。人皆知有用之用：人人都知道有用之物的用处。"},{id:"wuyong_yong",term:"无用之用也",pinyin:"wú yòng zhī yòng yě",meaning:"无用之物的用处（更深层的用途）。无用之用：无用之物所具有的更大用处；也：判断语气词。莫知无用之用：却没有人知道无用之物的用处——点明《人间世》全篇终极主旨。"}];return(D,i)=>{const c=y("DaoReadingPrelude"),t=y("DaoTextReading"),g=y("DaoKeywordCards"),s=y("DaoLineGuide");return f(),k("div",null,[i[0]||(i[0]=n("h1",{id:"庄子·人间世",tabindex:"-1"},[e("庄子·人间世 "),n("a",{class:"header-anchor",href:"#庄子·人间世","aria-label":'Permalink to "庄子·人间世"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"篇名释义",tabindex:"-1"},[e("篇名释义 "),n("a",{class:"header-anchor",href:"#篇名释义","aria-label":'Permalink to "篇名释义"'},"​")],-1)),i[2]||(i[2]=n("blockquote",null,[n("p",null,[n("strong",null,"「人间世」不是泛指日常生活，而是人置身于权力、责任、言语、利害与评价交织的险境。")]),n("p",null,"「世」有世道、世局之意。本篇写颜回欲入卫、叶公将使齐、颜阖将傅太子，看似人物各异，面对的却是同一个难题：当人不能退出某种关系与职责时，怎样行动而不把自己赔进去？"),n("p",null,"因而《人间世》不是教人一味避世，也不是鼓励硬闯。它从心斋、不得已、形就心和一路讲到无用之用，所要寻找的是在复杂处境中保身、保心、保有行动余地的方式。")],-1)),a(c,{title:"从心斋与无用之用，进入庄子的人间世",summary:"《人间世》是《庄子》内篇中最贴近现实处境的一篇。它把问题放进乱国、使命、传言、权力与人际关系之中，追问人在无法完全脱身的世界里，怎样说话、怎样行动，又怎样保全自己。",points:[{label:"先看",text:"顺着颜回、叶公、颜阖、匠石、接舆的故事，辨认不同险境。"},{label:"再问",text:"心斋、不得已与无用之用，如何从内在工夫走到现实处世？"},{label:"最后",text:"在不得不承担的关系和责任中，哪些用力其实正在消耗自己？"}],hint:"这篇不是一套圆滑的处世技巧。建议先看每个人面对的危险，再读庄子给出的边界与提醒。"}),i[3]||(i[3]=n("h2",{id:"一、颜回使卫·心斋",tabindex:"-1"},[e("一、颜回使卫·心斋 "),n("a",{class:"header-anchor",href:"#一、颜回使卫·心斋","aria-label":'Permalink to "一、颜回使卫·心斋"'},"​")],-1)),i[4]||(i[4]=n("h3",{id:"原文",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:r,glossary:m,"default-mode":"classic","aria-label":"人间世·颜回使卫心斋 原文"}),i[5]||(i[5]=n("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(g,{items:[{term:"奚之",pinyin:["xī","zhī"],meaning:"去哪里？奚：何、哪里；之：往、去。"},{term:"其行独",pinyin:["qí","xíng","dú"],meaning:"行事独断专行，不听他人意见。独：独断。"},{term:"轻用民死",pinyin:["qīng","yòng","mín","sǐ"],meaning:"轻易让百姓送死，不珍惜民命。"},{term:"泽若蕉",pinyin:["zé","ruò","jiāo"],meaning:"死者多得像泽中的蕉草一样，用国土来衡量都数不清。极言死亡之多。"},{term:"有瘳",pinyin:["yǒu","chōu"],meaning:"有所好转、痊愈。瘳：病愈，引申为好转。"},{term:"德荡乎名",pinyin:["dé","dàng","hū","míng"],meaning:"德行因追求名声而动摇散失。荡：动荡、散失。"},{term:"知出乎争",pinyin:["zhì","chū","hū","zhēng"],meaning:"智慧因争斗而显露，反而成为争斗的工具。知通「智」。"},{term:"相轧",pinyin:["xiāng","yà"],meaning:"相互倾轧、排挤。轧：碾压、排挤。"},{term:"德厚信矼",pinyin:["dé","hòu","xìn","gāng"],meaning:"德行深厚，诚信坚固。矼：坚固、坚实。"},{term:"菑人",pinyin:["zāi","rén"],meaning:"害人者。菑通「灾」，加害、伤害。"},{term:"关龙逢",pinyin:["guān","lóng","páng"],meaning:"夏桀时的忠臣，因直谏被杀。"},{term:"王子比干",pinyin:["wáng","zǐ","bǐ","gān"],meaning:"商纣王的叔父，因忠谏被剖心而死。"},{term:"伛拊人之民",pinyin:["yǔ","fǔ","rén","zhī","mín"],meaning:"俯身抚慰百姓，亲近民众。伛：弯腰俯身；拊：抚慰。"},{term:"虚室生白",pinyin:["xū","shì","shēng","bái"],meaning:"看那空旷之处，空的房间会生出光明。虚室生白：心空则智慧自生。"},{term:"吉祥止止",pinyin:["jí","xiáng","zhǐ","zhǐ"],meaning:"吉祥在静止中停驻。止止：停止、安静。"},{term:"坐驰",pinyin:["zuò","chí"],meaning:"身体坐着，心却在奔驰。形容心不能静，坐而神驰。"}]}),i[6]||(i[6]=n("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"先存诸己，才谈如何进入险境",subtitle:"一个内心未定的人，进入险恶的环境，只会被环境所化，而不是化环境。",lines:[{text:"古之至人，先存诸己而后存诸人。所存于己者未定，何暇至于暴人之所行！",tone:"次第",guide:"这是全段最根本的前提：先安顿自己，再去安顿别人。颜回自己的内心还没有定，就想去感化一个暴君——这不是勇气，是莽撞。一个内心未定的人，进入险恶的环境，只会被环境所化，而不是化环境。养生主说「缘督以为经」，人间世说「先存诸己」——是同一个道理的不同表述。"},{text:"德荡乎名，知出乎争。名也者，相轧也；知也者，争之器也。二者凶器，非所以尽行也。",tone:"动机",guide:"这是孔子对颜回动机的解剖：颜回想去卫国，表面上是救民，内心深处是否有「名」的驱动？他的「知」（智慧方案），是否会变成争斗的工具？名与知，本来是好东西，但一旦进入权力场，就变成凶器。不是名与知本身有问题，而是在那个场域里，它们必然被扭曲。"},{text:"菑人者，人必反菑之。",tone:"规律",guide:"这是人间世最现实的一条规律：你以为自己在帮他，他感受到的是被批评、被否定、被羞辱——你成了「菑人」，他必然反过来伤害你。强以仁义绳墨之言去说教暴君，不是在救他，是在激怒他。这不是道德问题，是人性规律。"},{text:"无听之以耳而听之以心，无听之以心而听之以气。",tone:"心斋",guide:"这是全篇最核心的段落，心斋的三个层次：耳听（信息层）、心听（判断层）、气听（虚静层）。心斋，就是从第一层、第二层，退到第三层——不是不听，而是听得更深，深到没有「我」在听。"},{text:"气也者，虚而待物者也。唯道集虚，虚者，心斋也。",tone:"定义",guide:"心斋的定义，庄子只用了十二个字：气，是一种虚静的存在状态；虚而待物，空虚地等待，不主动，不执着，不预设；唯道集虚，只有道，才能聚集于虚空之中；虚者，心斋，虚，就是心斋。心斋不是什么都不想，而是清空成见，让道自然流入。就像一个空的容器，才能盛水。"},{text:"一宅而寓于不得已，则几矣。",tone:"不得已",guide:"「不得已」——这是人间世处世的最高境界：不是主动想去，不是被迫不得不去，而是完全顺势，没有主观意图。「不得已」三个字，是庄子对「无为」在人间世中最精准的表达：不是什么都不做，而是做的每一件事，都是顺势而为，没有「我要」的执着。"},{text:"瞻彼阕者，虚室生白，吉祥止止。夫且不止，是之谓坐驰。",tone:"虚与驰",guide:"两个极美的意象：虚室生白——空的房间，光自然透进来。心空，智慧自然生起；坐驰——身体静坐，心却在奔驰。外表的静不是真静，心不空才是真正的躁动。「吉祥止止」——吉祥，停驻在静止之中。不是追来的，不是争来的，是在虚静中自然停驻的。"}]}),i[7]||(i[7]=n("h2",{id:"二、叶公子高使齐·两难困境",tabindex:"-1"},[e("二、叶公子高使齐·两难困境 "),n("a",{class:"header-anchor",href:"#二、叶公子高使齐·两难困境","aria-label":'Permalink to "二、叶公子高使齐·两难困境"'},"​")],-1)),i[8]||(i[8]=n("h3",{id:"原文-1",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:_,glossary:h,"default-mode":"classic","aria-label":"人间世·叶公子高使齐 原文"}),i[9]||(i[9]=n("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(g,{items:[{term:"叶公子高",pinyin:["shè","gōng","zǐ","gāo"],meaning:"楚国大夫，名诸梁，封于叶地，故称叶公。即「叶公好龙」典故中的叶公。"},{term:"甚敬而不急",pinyin:["shèn","jìng","ér","bù","jí"],meaning:"齐国对使者态度恭敬，但办事不紧不慢，不急于达成。"},{term:"吾甚栗之",pinyin:["wú","shèn","lì","zhī"],meaning:"我对此非常恐惧忧虑。栗：战栗、恐惧。"},{term:"人道之患",pinyin:["rén","dào","zhī","huàn"],meaning:"来自人事方面的祸患，如君主的责罚。"},{term:"阴阳之患",pinyin:["yīn","yáng","zhī","huàn"],meaning:"来自内心情绪失调的祸患，即焦虑、忧愁损耗身心。"},{term:"我其内热与",pinyin:["wǒ","qí","nèi","rè","yú"],meaning:"我大概是内心焦灼发热吧！内热：内心焦虑、烦躁。"},{term:"大戒",pinyin:["dà","jiè"],meaning:"最根本的戒律、不可违背的大原则。"},{term:"命也",pinyin:["mìng","yě"],meaning:"天命，与生俱来无法改变的。子女爱父母，是天性，是命。"},{term:"义也",pinyin:["yì","yě"],meaning:"道义，人伦关系中必须遵守的。臣子事君，是道义，是义。"},{term:"无适而非君",pinyin:["wú","shì","ér","fēi","jūn"],meaning:"无论走到哪里，都逃不开君臣关系。适：往、去。"},{term:"溢美之言",pinyin:["yì","měi","zhī","yán"],meaning:"过分夸赞的话，超出实情的美言。溢：超出、过分。"},{term:"溢恶之言",pinyin:["yì","è","zhī","yán"],meaning:"过分激烈的恶言，超出实情的批评之词。"},{term:"乘物以游心",pinyin:["chéng","wù","yǐ","yóu","xīn"],meaning:"顺应外物的自然变化，让心自由游走。乘：顺应、驾驭；游心：心灵自由游走，不执着。"}]}),i[10]||(i[10]=n("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"成与不成之外，怎样不先耗尽自己",subtitle:"无论成败，都有代价。问题不是「如何避免代价」，而是「如何在代价中保全内心」。",lines:[{text:"事若不成，则必有人道之患；事若成，则必有阴阳之患。",tone:"两难",guide:"这是人间世最核心的两难困境：事不成有君主责罚（外部惩罚），事若成有内心焦虑损耗（内部伤害）。无论成败，都有代价。这不是悲观，而是庄子对「人间世」最诚实的描述：在权力结构里做事，没有全身而退的完美方案。问题不是「如何避免代价」，而是「如何在代价中保全内心」。"},{text:"天下有大戒二：其一，命也；其一，义也。",tone:"大戒",guide:"孔子的回答，先不给方法，先给定位：有些事，是逃不掉的。爱父母是天命，无法解除；事君主是道义，无处可逃。「无所逃于天地之间」——这六个字，是庄子对人间世处境最冷静的判断。不是恐吓，而是解放：既然逃不掉，就不要把精力放在「如何逃」上，而是放在「如何在逃不掉的处境里，保全内心」。"},{text:"知其不可奈何而安之若命，德之至也。",tone:"安命",guide:"这句话与养生主的「安时而处顺」完全呼应，是庄子处世哲学的核心：知其不可奈何（清醒地认识到有些事无法改变）→ 安之若命（把它当作天命一样安然接受）→ 德之至（这是德行的最高境界）。不是认命的消极，而是在清醒认知之后的主动接受。这与「躺平」的区别在于：躺平是逃避，安之若命是在接受之后，依然全力去做该做的事。"},{text:"传其常情，无传其溢言，则几乎全。",tone:"传言",guide:"这是孔子给出使者最实用的一条操作准则：传常情（传达平实、正常的实情），无传溢言（不传达过激、夸大的言辞）。两国之间，最危险的不是实情，而是溢言。喜悦时的溢美之词，愤怒时的激烈之辞——这些话传过去，必然失真，必然殃及传话者。做一个忠实的传递者，而不是情绪的放大器。"},{text:"其作始也简，其将毕也必巨。",tone:"慎始",guide:"这是人间世里最值得警惕的一条规律：事情开始时总是简单的，到结束时必然变得复杂巨大。言语如此——一句无心的话，最后可能酿成大祸；行动如此——一个小小的决定，最后可能牵连无数。「可不慎与！」——庄子借孔子之口，发出这篇里最直接的警告。"},{text:"乘物以游心，托不得已以养中，至矣。",tone:"至矣",guide:"全段的收尾，也是庄子给出使者的终极答案，只有十二个字：乘物以游心（顺应外物的变化，让心自由游走，不执着于结果），托不得已以养中（寄托于「不得已」的顺势状态，滋养内心的中正平和），至矣（这就是最高境界了）。「不得已」再次出现——这是人间世处世的最高法则：顺势而为，没有「我要」的执着，没有「我怕」的恐惧。"}]}),i[11]||(i[11]=n("h2",{id:"三、颜阖将傅卫太子·养虎之道",tabindex:"-1"},[e("三、颜阖将傅卫太子·养虎之道 "),n("a",{class:"header-anchor",href:"#三、颜阖将傅卫太子·养虎之道","aria-label":'Permalink to "三、颜阖将傅卫太子·养虎之道"'},"​")],-1)),i[12]||(i[12]=n("h3",{id:"原文-2",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:o,glossary:d,"default-mode":"classic","aria-label":"人间世·颜阖养虎之道 原文"}),i[13]||(i[13]=n("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(g,{items:[{term:"颜阖",pinyin:["yán","hé"],meaning:"卫国贤人，隐士。"},{term:"傅",pinyin:["fù"],meaning:"辅导、教导。太子傅：太子的老师。"},{term:"蘧伯玉",pinyin:["qú","bó","yù"],meaning:"卫国大夫，以德行著称，孔子的朋友。"},{term:"其德天杀",pinyin:["qí","dé","tiān","shā"],meaning:"他的德行天生残缺凶暴。天杀：天生的戾气，杀伐之性。"},{term:"与之为无方",pinyin:["yǔ","zhī","wéi","wú","fāng"],meaning:"对他不加约束、顺着他来。无方：没有规矩方法。"},{term:"与之为有方",pinyin:["yǔ","zhī","wéi","yǒu","fāng"],meaning:"对他加以规矩约束、正面教导。有方：有规矩方法。"},{term:"町畦",pinyin:["tǐng","qí"],meaning:"田间的界限、畦垄。比喻规矩界限。无町畦：不守规矩、随心所欲。"}]}),i[14]||(i[14]=n("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"形随而心不随，是人间世最高难度的处世艺术",subtitle:"面对危险人物，不是对抗，也不是同化，而是外顺而内不失。",lines:[{text:"其知适足以知人之过，而不知其所以过。",tone:"画像",guide:"这是庄子对「危险人物」最精准的画像：智力恰好够发现别人的错误，却完全看不见自己为什么会犯错。这种人最难相处——因为他永远是对的，你永远是错的。颜阖面对的，不只是一个暴戾的太子，而是一个自我封闭的权力系统。任何正面的教导，都会被他解读为对自己的攻击。"},{text:"形莫若就，心莫若和。就不欲入，和不欲出。",tone:"边界",guide:"蘧伯玉给出的方法，精妙在这四句的张力：外形（行为）顺从（就），但不要真的陷入（不欲入）；内心（态度）和顺（和），但不要表露出来（不欲出）。外顺而内不失，和而不同流。这不是虚伪，而是在危险处境中保全自身的智慧。形就而入：同流合污，最终与他一起覆灭；心和而出：变成谄媚，反而招来祸孽。"},{text:"彼且为婴儿，亦与之为婴儿；彼且为无町畦，亦与之为无町畦。",tone:"形随",guide:"这三句是「形就」的具体展开：他怎样，你就跟着怎样——在形式上。他像婴儿一样任性，你也跟着像婴儿；他不守规矩，你也跟着不守规矩。但内心始终清醒，始终保持那条看不见的边界。这是人间世里最高难度的处世艺术：形随而心不随。"},{text:"螳螂怒其臂以当车辙，不知其不胜任也。",tone:"警告",guide:"螳螂臂的比喻，是给颜阖的第一个警告：不要用自己的才能美德去正面对抗太子。螳螂的臂膀是它最美的东西，但拿来挡车轮，只是送死。颜阖的学识、德行，是他最好的东西，但若拿来在太子面前「积伐而美」——炫耀、说教、纠正——结果与螳螂无异。"},{text:"时其饥饱，达其怒心。虎之与人异类而媚养己者，顺也；故其杀者，逆也。",tone:"养虎",guide:"养虎的比喻，是全段最深刻的一层：养虎者不敢给活物，不敢给整物——因为怕触发虎的杀性；要掌握它饥饱的时机，通达它怒气的规律。虎亲近养它的人，是因为人顺应了它的天性；虎杀人，是因为人违逆了它的天性。太子就是那只虎。颜阖的任务不是驯虎，而是养虎——顺应它，不触逆它，在它的天性里找到共处的方式。"},{text:"意有所至而爱有所亡，可不慎邪！",tone:"慎",guide:"全段最后一句，也是最令人警醒的一句：爱马者，本意是爱护马，却因为拍打时机不对，反而被马所伤。出发点是爱，结果是伤——这是人间世里最常见的悲剧。不是动机有问题，而是方法与时机有问题。「可不慎邪」——庄子再次发出警告：谨慎，谨慎，再谨慎。"}]}),i[15]||(i[15]=n("h2",{id:"四、匠石梦栎·无用之用",tabindex:"-1"},[e("四、匠石梦栎·无用之用 "),n("a",{class:"header-anchor",href:"#四、匠石梦栎·无用之用","aria-label":'Permalink to "四、匠石梦栎·无用之用"'},"​")],-1)),i[16]||(i[16]=n("h3",{id:"原文-3",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:u,glossary:l,"default-mode":"classic","aria-label":"人间世·匠石梦栎 原文"}),i[17]||(i[17]=n("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(g,{items:[{term:"匠石",pinyin:["jiàng","shí"],meaning:"名叫石的木匠，能工巧匠。"},{term:"曲辕",pinyin:["qū","yuán"],meaning:"地名，在齐国境内。"},{term:"栎社树",pinyin:["lì","shè","shù"],meaning:"生长在土地神祠旁的栎树。栎：落叶乔木，木质疏松，不堪为材。社：土地神的祭坛。"},{term:"蔽数千牛",pinyin:["bì","shù","qiān","niú"],meaning:"树荫能遮蔽数千头牛。极言树冠之大。"},{term:"絜之百围",pinyin:["xié","zhī","bǎi","wéi"],meaning:"树干周长达百围之粗。絜：度量、测量；围：两手合抱为一围。"},{term:"观者如市",pinyin:["guān","zhě","rú","shì"],meaning:"围观的人多得像集市一样。"},{term:"匠伯不顾",pinyin:["jiàng","bó","bù","gù"],meaning:"匠石头也不回。伯：对匠人的尊称。"},{term:"散木",pinyin:["sàn","mù"],meaning:"无用之木，不成材的木头。散：散漫、无用。"},{term:"液樠",pinyin:["yè","mán"],meaning:"渗出汁液，容易腐朽变形。液：渗液；樠：木材渗出的汁液。"},{term:"蠹",pinyin:["dù"],meaning:"被虫蛀蚀。蠹：蛀虫，引申为被虫蛀。"},{term:"文木",pinyin:["wén","mù"],meaning:"有纹理、有用处的木材。与「散木」相对。"}]}),i[18]||(i[18]=n("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"无用之用，是人间世里最深的生存智慧",subtitle:"不是什么都不做，而是不让自己成为权力与欲望的工具。",lines:[{text:"散木也……无所可用，故能若是之寿。",tone:"无用",guide:"匠石的判断，是从「有用」的角度出发的：这棵树一无是处——造船沉、做棺腐、为器毁、作门液、当柱蠹。正因为无用，所以没人砍它，所以活了这么久。匠石说这话，本是轻蔑，却无意中道出了庄子的核心命题：无用，是一种保全生命的智慧。"},{text:"实熟则剥，剥则辱；大枝折，小枝泄。此以其能苦其生者也。",tone:"有用之祸",guide:"栎树在梦中反驳，用果树作比：果树有用——结果、供人摘取——但正是这个「有用」，让它们枝折叶损，不得善终。「以其能苦其生」——才能，成了苦难的根源。这是庄子对「有用」最深刻的解构：你以为有用是好事，但在人间世，有用意味着被消耗、被利用、被榨干。"},{text:"且予求无所可用久矣，几死，乃今得之，为予大用。",tone:"主动",guide:"栎树说出了整个故事最震撼的一句话：我追求无用，已经追求很久了。不是天生无用，而是主动求无用——这才是庄子真正要说的：无用不是消极的结果，而是积极的选择，是一种生存策略，是一种处世智慧。「无用」，是栎树的「大用」。"},{text:"使予也而有用，且得有此大也邪？",tone:"反问",guide:"这是全段最有力的反问：如果我是有用之材，我还能长这么大吗？答案显然是否定的——早就被砍了。庄子用这一句，把「无用之用」的逻辑说得无可辩驳：正是无用，才有了生存的空间；正是生存的空间，才有了参天的高度。无用，是最大的用。"},{text:"彼亦直寄焉，以为不知己者诟厉也。不为社者，且几有翦伐哉！",tone:"借势",guide:"匠石醒来后对弟子说的这句话，是全段最冷静的一层：栎树借「社树」的名义保全自己——不是真的要做神树，而是借一个世俗认可的身份，来抵挡世俗的砍伐。这是无用之用的第二层：懂得借势，懂得用世俗的规则保护自己。完全的「无用」在人间世是危险的，所以栎树寄身于社树之名——用一点点「有用」的外壳，保护内心真正的「无用」。"},{text:"彼其所保与众异，而以义誉之，不亦远乎！",tone:"本真",guide:"匠石最后这句话，是对弟子天真想法的纠正：弟子说，故意追求无用，就成社树了——匠石说，你根本没懂。栎树保全的，是生命本身，不是什么仁义道德。用世俗的「义」来称赞它，差得太远了。庄子借匠石之口，划出了一条清晰的界线：无用之用，不是道德，不是策略，是对生命本身的忠实。"}]}),i[19]||(i[19]=n("h2",{id:"五、南伯子綦游商丘·大木之异",tabindex:"-1"},[e("五、南伯子綦游商丘·大木之异 "),n("a",{class:"header-anchor",href:"#五、南伯子綦游商丘·大木之异","aria-label":'Permalink to "五、南伯子綦游商丘·大木之异"'},"​")],-1)),i[20]||(i[20]=n("h3",{id:"原文-4",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:x,glossary:p,"default-mode":"classic","aria-label":"人间世·南伯子綦游商丘 原文"}),i[21]||(i[21]=n("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(g,{items:[{term:"南伯子綦",pinyin:["nán","bó","zǐ","qí"],meaning:"道家人物，齐物论中亦有出现。南伯：南方之伯；子綦：名字。"},{term:"商之丘",pinyin:["shāng","zhī","qiū"],meaning:"地名，宋国境内的商丘。"},{term:"结驷千乘",pinyin:["jié","sì","qiān","shèng"],meaning:"数千辆四马之车聚集在一起。极言树荫之广大。"},{term:"拳曲",pinyin:["quán","qū"],meaning:"弯曲盘旋，不能伸直。拳：弯曲如拳。"},{term:"轴解",pinyin:["zhóu","jiě"],meaning:"木质疏松，像车轴一样容易裂开散解。轴：车轴；解：裂开、散开。"},{term:"咶其叶",pinyin:["guā","qí","yè"],meaning:"舔舐它的叶子。咶：舔、舐。"},{term:"狂酲",pinyin:["kuáng","chéng"],meaning:"像喝醉酒一样神志昏乱。酲：醉后神志不清。"},{term:"荆氏",pinyin:["jīng","shì"],meaning:"地名，宋国的一个地方，适合种植树木。"},{term:"拱把而上者",pinyin:["gǒng","bǎ"],meaning:"粗细达到一两手合围的树。拱：两手合围；把：一手握住。"},{term:"桁杨",pinyin:["háng","yáng"],meaning:"古代一种刑具，套在脚上的木枷。"},{term:"豚之亢鼻者",pinyin:["tún","zhī","kàng","bí"],meaning:"鼻子朝天的猪。亢鼻：鼻孔朝上。"},{term:"不可以适河",pinyin:["bù","kě","yǐ","shì","hé"],meaning:"不可以用来祭祀河神（因为有缺陷，不合祭祀规格）。"}]}),i[22]||(i[22]=n("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"不材，故得参天——「不祥」是最大的吉祥",subtitle:"世俗追求的「完美有用」，是通往死亡的路；世俗鄙视的「残缺无用」，是通往长生的路。",lines:[{text:"此果不材之木也，以至于此其大也。嗟乎神人，以此不材！",tone:"不材",guide:"南伯子綦一开始以为这棵树有异材，仔细观察后发现：枝拳曲不能为栋梁，根轴解不能为棺椁，叶烂口，气醉人——一无是处。然后他恍然大悟：正因为一无是处，才长成了这个参天的大小。这与第四段栎树的逻辑完全呼应，但这里庄子更进一步：神人，也是用这种「不材」来保全自己的。无用，不只是树的智慧，是得道之人的处世之道。"},{text:"宋有荆氏者……此皆以其材之患也，故未终其天年而中道之夭。",tone:"有用之祸",guide:"庄子用荆氏之地的树木，把「有用之祸」列得清清楚楚：拱把之木被斩作拴猴木桩，三四围之木被斩作房屋栋梁，七八围之木被斩作车轮材料，十围之木被斩作刑具桁杨。越有用，死得越早。没有一棵树能活完天年——因为它们的「材」，恰好符合了某种人的需求。庄子在这里说的不只是树，而是人间世里所有「有用之人」的命运。"},{text:"不择地而生，此其以材伤也。",tone:"冷峻",guide:"这一句极为冷峻：不管生在哪里，只要有用，就会受伤。不是环境的问题，不是运气的问题，而是「有用」本身，就是祸根。庄子把这个逻辑推到极致：桀纣的暴行，汤武的征战——也都是「以材伤」。桀纣有暴虐之「材」，汤武有征战之「材」——这些「材」，最终都造成了巨大的伤害与破坏。"},{text:"此乃神人之所以为大祥也。",tone:"翻转",guide:"全段最后的翻转，也是庄子最精妙的一笔：白额的牛、朝天鼻的猪、有痔疮的人——世俗认为这些是「不祥」，不能用来祭祀。但庄子说：这恰恰是神人眼中的「大祥」。因为有缺陷，所以不被选中；因为不被选中，所以得以保全。「不祥」，是最大的吉祥。这是人间世里最深的反讽：世俗追求的「完美有用」，是通往死亡的路；世俗鄙视的「残缺无用」，是通往长生的路。"}]}),i[23]||(i[23]=n("h2",{id:"六、支离疏·形残而德全",tabindex:"-1"},[e("六、支离疏·形残而德全 "),n("a",{class:"header-anchor",href:"#六、支离疏·形残而德全","aria-label":'Permalink to "六、支离疏·形残而德全"'},"​")],-1)),i[24]||(i[24]=n("h3",{id:"原文-5",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:z,glossary:b,"default-mode":"classic","aria-label":"人间世·支离疏 原文"}),i[25]||(i[25]=n("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(g,{items:[{term:"支离疏",pinyin:["zhī","lí","shū"],meaning:"虚构人物，名字本身即含「支离破碎、疏散」之意。"},{term:"颐隐于脐",pinyin:["yí","yǐn","yú","qí"],meaning:"下巴藏在肚脐里。颐：下巴；脐：肚脐。极言身体畸形之甚。"},{term:"肩高于顶",pinyin:["jiān","gāo","yú","dǐng"],meaning:"两肩高过头顶。"},{term:"会撮指天",pinyin:["huì","cuō","zhǐ","tiān"],meaning:"发髻朝天竖起。会撮：发髻；指天：朝向天空。"},{term:"五管在上",pinyin:["wǔ","guǎn","zài","shàng"],meaning:"五脏的经脉都翻转朝上。指身体严重扭曲变形。"},{term:"两髀为胁",pinyin:["liǎng","bì","wéi","xié"],meaning:"两条大腿与两肋并排在一起。髀：大腿；胁：肋骨两侧。"},{term:"挫针治繲",pinyin:["cuò","zhēn","zhì","xiè"],meaning:"用针缝补浆洗衣物。挫针：用针缝纫；治繲：浆洗衣物。"},{term:"鼓筴播精",pinyin:["gǔ","cè","bō","jīng"],meaning:"摇动簸箕筛选米粮。鼓筴：摇动簸箕；播精：筛去糠秕，留下精米。"},{term:"上征武士",pinyin:["shàng","zhēng","wǔ","shì"],meaning:"官府征召士兵服役。上：官府、上级；征：征召。"},{term:"支离其形者",pinyin:["zhī","lí","qí","xíng"],meaning:"形体残缺支离的人。"},{term:"支离其德者",pinyin:["zhī","lí","qí","dé"],meaning:"德行支离散漫（不拘于世俗道德规范）的人。形残尚可保身，德散更能全生。"}]}),i[26]||(i[26]=n("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"残缺，在这里是一种自由",subtitle:"形体的残缺是被动的，德行的「支离」是主动的选择。",lines:[{text:"上征武士，则支离攘臂而游于其间。",tone:"自由",guide:"这个细节极为生动：征兵的队伍里，所有人都战战兢兢，只有支离疏扬着臂膀自由走动——因为他残缺，所以没人要他。残缺，在这里是一种自由。庄子用这个极端的例子，把「无用之用」推到了人身上：不只是树可以用无用保全自己，人也可以。"},{text:"夫支离其形者，犹足以养其身，终其天年，又况支离其德者乎！",tone:"点睛",guide:"全段的点睛之笔，也是庄子真正要说的话：支离其形（形体残缺）——尚且能养身终年；支离其德（德行不拘于世俗规范）——更能全生。形体的残缺是被动的，德行的「支离」是主动的选择。庄子在这里说的「支离其德」，不是道德败坏，而是不让自己的德行成为被世俗利用、消耗的工具——就像栎树的无用，就像大木的不材，德行的「散漫」，是人间世里保全生命的最高智慧。"}]}),i[27]||(i[27]=n("h2",{id:"七、接舆歌·孔丘之危",tabindex:"-1"},[e("七、接舆歌·孔丘之危 "),n("a",{class:"header-anchor",href:"#七、接舆歌·孔丘之危","aria-label":'Permalink to "七、接舆歌·孔丘之危"'},"​")],-1)),i[28]||(i[28]=n("h3",{id:"原文-6",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-6","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:q,glossary:w,"default-mode":"classic","aria-label":"人间世·接舆歌 原文"}),i[29]||(i[29]=n("h3",{id:"生僻字词-6",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(g,{items:[{term:"孔子适楚",pinyin:["kǒng","zǐ","shì","chǔ"],meaning:"孔子前往楚国。适：前往。"},{term:"楚狂接舆",pinyin:["chǔ","kuáng","jiē","yú"],meaning:"楚国的狂人接舆，著名隐士，佯狂避世。狂：佯狂，装疯。"},{term:"凤兮凤兮",pinyin:["fèng","xī","fèng","xī"],meaning:"凤凰啊凤凰啊！以凤凰比喻孔子，凤凰是圣德之鸟，只在天下有道时出现。"},{term:"临人以德",pinyin:["lín","rén","yǐ","dé"],meaning:"用德行去感化、教导别人。临：居高临下、面对。"},{term:"画地而趋",pinyin:["huà","dì","ér","qū"],meaning:"在地上画出界线然后奔走其中。比喻用礼义规范来约束自己和别人，反而限制了自由。"},{term:"迷阳",pinyin:["mí","yáng"],meaning:"一种有刺的植物，比喻世间的险阻与危难。"},{term:"吾行却曲",pinyin:["wú","xíng","què","qū"],meaning:"我的路迂回曲折。却曲：弯曲迂回。"},{term:"山木自寇也",pinyin:["shān","mù","zì","kòu","yě"],meaning:"山上的树木自己招来了砍伐之祸。寇：侵害、砍伐。因为有用，所以自招其害。"},{term:"膏火自煎也",pinyin:["gāo","huǒ","zì","jiān","yě"],meaning:"油脂因为能燃烧而自我煎熬。膏：油脂；煎：煎熬、燃烧耗尽。"}]}),i[30]||(i[30]=n("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"人皆知有用之用，而莫知无用之用",subtitle:"「无用之用」，是人间世全篇的灵魂，也是庄子给乱世中人最深的礼物。",lines:[{text:"凤兮凤兮，何如德之衰也！",tone:"凤凰",guide:"接舆以凤凰比孔子——这是极高的赞美，也是极深的悲悯：凤凰只在天下有道时出现，如今天下无道，凤凰出现，不是祥瑞，而是悲剧。接舆不是在嘲笑孔子，而是在为孔子痛惜：你是凤凰，却生在了不该出现的时代。"},{text:"天下有道，圣人成焉；天下无道，圣人生焉。",tone:"冷峻",guide:"这是人间世全篇最冷静的一句判断，也是庄子对儒家最深的批评：天下有道，圣人可以出来做事，成就功业；天下无道，圣人只能保全生命，活下去就是全部。「生焉」——活着，就是乱世圣人的全部使命。孔子周游列国，想要「成焉」，但接舆告诉他：这个时代，「生焉」已经是最难的事了。"},{text:"福轻乎羽，莫之知载；祸重乎地，莫之知避。",tone:"警句",guide:"这两句是人间世里最美的警句：福气比羽毛还轻——轻到没有人知道怎么承载；祸患比大地还重——重到没有人知道怎么躲避。不是福祸本身难以把握，而是人不知道。不知道福从何来，所以抓不住；不知道祸从何来，所以躲不开。这是人间世里最普遍的困境：不是没有智慧，而是不知道用在哪里。"},{text:"已乎已乎，临人以德！殆乎殆乎，画地而趋！",tone:"警告",guide:"接舆的劝告，直指孔子的两个根本问题：临人以德——用德行居高临下地感化别人，别人感受到的是被评判、被俯视，必然反弹（与第一段「菑人者，人必反菑之」完全呼应）；画地而趋——用礼义给自己画了一个圈，然后在这个圈里拼命奔走，圈子本身就是束缚，越努力越危险。"},{text:"迷阳迷阳，无伤吾行！吾行却曲，无伤吾足！",tone:"绕道",guide:"接舆最后唱的这几句，是给自己的，也是给孔子的：荆棘啊荆棘，我绕着走，不让你伤我的脚——在险恶的世道里，懂得绕道，才是真正的智慧。不是逃避，而是：不硬闯，不以卵击石，找到那条弯曲却安全的路。"},{text:"山木自寇也，膏火自煎也。",tone:"自害",guide:"全篇最后两个意象，极为精炼：山木自寇——树木因为有用，自己招来了砍伐；膏火自煎——油脂因为能燃烧，自己把自己煎熬殆尽。「自」字是关键——不是别人害了它们，是它们自己的「有用」害了自己。这是庄子对「有用之祸」最后的总结，也是最深的悲悯。"},{text:"人皆知有用之用，而莫知无用之用也。",tone:"终极",guide:"这是人间世全篇的终极结语，也是庄子最著名的一句话：人人都知道有用的用处，却没有人知道无用的用处。回望全篇：心斋（清空自我，以虚待物）、不得已（顺势而为，无主观执着）、栎树（主动求无用，以无用为大用）、大木（不材，故得参天）、支离疏（形残，故免征役）、接舆（佯狂，故得自由）——「无用之用」，是人间世全篇的灵魂，也是庄子给乱世中人最深的礼物。"}]}),i[31]||(i[31]=P("",45))])}}});export{G as __pageData,N as default};
